-- HD2-Addon: mods/cowboybingus/mod_options_menu
-- Generated by scripts/build.py from src/bingus_text.lua, locales/en.lua, src/api.lua, src/bingus_memory.lua, src/bingus_runtime.lua, src/native.lua, src/options.lua, src/rows.lua, src/view.lua, src/widgets.lua and src/mod_options_menu.lua; edit those instead.
local mom_text = {module = (function()
-- Bingus Text v1: translations and UTF-8 text layout for CowboyBingus mods.
--
-- Canonical copy: Translations/bingus_text.lua in the workspace. Every mod
-- that shows text carries a byte-identical src/bingus_text.lua. Copies share
-- translations only through the plain-data table _G.BingusTranslations, never
-- through functions, so mods built with different copies still agree:
--
--   version         1
--   serial          bumped by every change below; mods compare it to notice
--   packs           {language = 'zh-Hans', name = '...', force = false,
--                    mods = {mod_id = {key = text}}}
--   override        language of the last pack registered with force = true
--   game_language   tag of the game's Text Language setting, from game memory
--   game_code       that setting's own code (for example 'us')
--   steam_language  tag of Steam's game language (false when unknown)
--
-- Nothing here runs per frame. A mod resolves its texts when it builds its
-- UI; tr:refresh() costs one global read and two compares when nothing
-- changed. System calls: five memory reads through the mod's own reader
-- when it observes the game's language, and the Steam language query once
-- per session when that fails (both unmeasured in game).
local M = {VERSION = 1}

local byte, char, concat = string.byte, string.char, table.concat

-- The code point at byte i and the byte after it, or nil when the bytes at i
-- are not valid UTF-8 (overlong forms, surrogates and values above U+10FFFF
-- are invalid).
function M.decode(text, i)
    local c = byte(text, i)
    if not c then return nil end
    if c < 0x80 then return c, i + 1 end
    local n, value
    if c >= 0xC2 and c <= 0xDF then n, value = 1, c - 0xC0
    elseif c >= 0xE0 and c <= 0xEF then n, value = 2, c - 0xE0
    elseif c >= 0xF0 and c <= 0xF4 then n, value = 3, c - 0xF0
    else return nil end
    local lo, hi = 0x80, 0xBF
    if c == 0xE0 then lo = 0xA0 elseif c == 0xED then hi = 0x9F
    elseif c == 0xF0 then lo = 0x90 elseif c == 0xF4 then hi = 0x8F end
    for k = 1, n do
        local d = byte(text, i + k)
        if not d or d < lo or d > hi then return nil end
        value = value * 64 + (d - 0x80)
        lo, hi = 0x80, 0xBF
    end
    return value, i + n + 1
end

-- UTF-8 bytes of one code point.
function M.encode(value)
    if value < 0x80 then return char(value) end
    if value < 0x800 then return char(0xC0 + math.floor(value / 64), 0x80 + value % 64) end
    if value < 0x10000 then
        return char(0xE0 + math.floor(value / 4096), 0x80 + math.floor(value / 64) % 64, 0x80 + value % 64)
    end
    return char(0xF0 + math.floor(value / 262144), 0x80 + math.floor(value / 4096) % 64,
        0x80 + math.floor(value / 64) % 64, 0x80 + value % 64)
end

-- Text a mod may show: valid UTF-8 without control characters (a line feed
-- only where `multiline` allows it). Returns the text, or nil and the reason.
function M.check(text, multiline)
    if type(text) ~= 'string' then return nil, 'not a string' end
    local i, n = 1, #text
    while i <= n do
        local value, after = M.decode(text, i)
        if not value then return nil, 'invalid UTF-8 at byte ' .. i end
        if (value < 32 and not (multiline and value == 10)) or value == 127 or (value >= 0x80 and value < 0xA0) then
            return nil, 'control character at byte ' .. i
        end
        i = after
    end
    return text
end

-- check() that raises. Replaces the old plain-ASCII guards.
function M.display(text, multiline)
    local ok, why = M.check(text, multiline)
    if not ok then error('Unsupported display text: ' .. why, 2) end
    return text
end

-- Number of code points.
function M.length(text)
    local count, i, n = 0, 1, #text
    while i <= n do
        local _, after = M.decode(text, i)
        i, count = after or i + 1, count + 1
    end
    return count
end

-- Upper case for the scripts the game's fonts carry: ASCII, Latin-1, Latin
-- Extended-A (Polish, Czech...), Greek and Cyrillic. string.upper changes only
-- a-z, so 'Plongee' with an accent would come out half upper-cased. Other
-- characters (CJK, digits, sharp s) stay as they are.
local function upper_value(v)
    if v < 0x80 then return (v >= 0x61 and v <= 0x7A) and v - 32 or v end
    if v >= 0xE0 and v <= 0xFE and v ~= 0xF7 then return v - 32 end
    if v == 0xFF then return 0x178 end
    if v >= 0x100 and v <= 0x17F then
        if v == 0x131 then return 0x49 end
        if v == 0x17F then return 0x53 end
        if (v >= 0x139 and v <= 0x148) or (v >= 0x179 and v <= 0x17E) then
            return v % 2 == 0 and v - 1 or v
        end
        if v ~= 0x138 and v ~= 0x149 and v ~= 0x130 then return v % 2 == 1 and v - 1 or v end
        return v
    end
    if v >= 0x3B1 and v <= 0x3CB then return v == 0x3C2 and 0x3A3 or v - 32 end
    if v == 0x3AC then return 0x386 end
    if v >= 0x3AD and v <= 0x3AF then return v - 37 end
    if v == 0x3CC then return 0x38C end
    if v == 0x3CD or v == 0x3CE then return v - 63 end
    if v >= 0x430 and v <= 0x44F then return v - 32 end
    if v >= 0x450 and v <= 0x45F then return v - 80 end
    if v == 0x491 then return 0x490 end
    return v
end

function M.upper(text)
    if not text:find('[\97-\122\128-\255]') then return text end
    local parts, i, n = {}, 1, #text
    while i <= n do
        local value, after = M.decode(text, i)
        local changed = value and upper_value(value)
        if not value then after = i + 1 end
        parts[#parts + 1] = changed and changed ~= value and M.encode(changed) or text:sub(i, after - 1)
        i = after
    end
    return concat(parts)
end

-- The longest start of `text` that fits in `bytes` without cutting a
-- character: for the game's fixed-size text buffers.
function M.clip(text, bytes)
    if #text <= bytes then return text end
    local i = bytes + 1
    while i > 1 do
        local b = byte(text, i)
        if b < 0x80 or b >= 0xC0 then break end
        i = i - 1
    end
    return text:sub(1, i - 1)
end

local function set(list)
    local result = {}
    for _, value in ipairs(list) do result[value] = true end
    return result
end

-- Line breaking, a small subset of Unicode UAX #14. Never break before
-- closing punctuation, small kana or the prolonged sound mark, or after
-- opening punctuation and currency signs.
local CLOSE = set({0x21, 0x25, 0x29, 0x2C, 0x2E, 0x3A, 0x3B, 0x3F, 0x5D, 0x7D,
    0x2010, 0x2013, 0x2019, 0x201D, 0x2025, 0x2026, 0x2030, 0x2103,
    0x3001, 0x3002, 0x3005, 0x3009, 0x300B, 0x300D, 0x300F, 0x3011, 0x3015, 0x3017, 0x3019, 0x301B,
    0x301C, 0x301E, 0x301F, 0x303B,
    0x3041, 0x3043, 0x3045, 0x3047, 0x3049, 0x3063, 0x3083, 0x3085, 0x3087, 0x308E, 0x3095, 0x3096,
    0x309B, 0x309C, 0x309D, 0x309E, 0x30A0, 0x30A1, 0x30A3, 0x30A5, 0x30A7, 0x30A9, 0x30C3, 0x30E3,
    0x30E5, 0x30E7, 0x30EE, 0x30F5, 0x30F6, 0x30FB, 0x30FC, 0x30FD, 0x30FE,
    0xFF01, 0xFF05, 0xFF09, 0xFF0C, 0xFF0E, 0xFF1A, 0xFF1B, 0xFF1F, 0xFF3D, 0xFF5D, 0xFF5E, 0xFF60,
    0xFF61, 0xFF63, 0xFF64, 0xFF65})
local OPEN = set({0x24, 0x28, 0x5B, 0x7B, 0xA3, 0xA5, 0x2018, 0x201C, 0x20A9, 0x20AC,
    0x3008, 0x300A, 0x300C, 0x300E, 0x3010, 0x3014, 0x3016, 0x3018, 0x301A, 0x301D,
    0xFF04, 0xFF08, 0xFF3B, 0xFF5B, 0xFF5F, 0xFF62, 0xFFE1, 0xFFE5})
local ZWJ = 0x200D

-- Characters that belong to the one before them: combining marks, joiners,
-- variation selectors, emoji skin tones, Hangul vowel and final jamo.
local function mark(v)
    return (v >= 0x300 and v <= 0x36F) or (v >= 0x483 and v <= 0x489) or v == 0xE31
        or (v >= 0xE34 and v <= 0xE3A) or (v >= 0xE47 and v <= 0xE4E) or (v >= 0x1160 and v <= 0x11FF)
        or (v >= 0x1AB0 and v <= 0x1AFF) or (v >= 0x1DC0 and v <= 0x1DFF) or v == 0x200C or v == ZWJ
        or (v >= 0x20D0 and v <= 0x20FF) or v == 0x3099 or v == 0x309A or (v >= 0xFE00 and v <= 0xFE0F)
        or (v >= 0xFE20 and v <= 0xFE2F) or (v >= 0x1F3FB and v <= 0x1F3FF) or (v >= 0xE0100 and v <= 0xE01EF)
end

-- Scripts written without spaces between words (Chinese, Japanese) and
-- Korean syllables: a line may break before or after any of these.
local function wide(v)
    return (v >= 0x1100 and v <= 0x115F) or (v >= 0x2E80 and v <= 0xA4CF) or (v >= 0xA960 and v <= 0xA97F)
        or (v >= 0xAC00 and v <= 0xD7FF) or (v >= 0xF900 and v <= 0xFAFF) or (v >= 0xFE10 and v <= 0xFE1F)
        or (v >= 0xFE30 and v <= 0xFE4F) or (v >= 0xFF00 and v <= 0xFF60) or (v >= 0xFFE0 and v <= 0xFFE6)
        or (v >= 0x1F300 and v <= 0x1FAFF) or (v >= 0x20000 and v <= 0x3FFFD)
end

local function space(v) return v == 32 or v == 0x3000 end

-- Byte offsets where each user-perceived character starts (a code point plus
-- the marks that follow it), then #text + 1. Scrolling and forced breaks cut
-- only here, so no character is ever split.
function M.boundaries(text)
    local list, i, n, previous = {}, 1, #text, nil
    while i <= n do
        local value, after = M.decode(text, i)
        if not value then value, after = 0xFFFD, i + 1 end
        if not previous or not (mark(value) or previous == ZWJ) then list[#list + 1] = i end
        previous, i = value, after
    end
    list[#list + 1] = n + 1
    return list
end

-- Unbreakable pieces of text: {first byte, last byte, separator before it,
-- line feeds before it}.
local function pieces(text)
    local list, i, n = {}, 1, #text
    local first, last, previous, gap, feeds = nil, nil, nil, '', 0
    local function finish()
        if first then
            list[#list + 1] = {first, last, gap, feeds}
            gap, feeds = '', 0
        end
        first = nil
    end
    while i <= n do
        local value, after = M.decode(text, i)
        if not value then value, after = 0xFFFD, i + 1 end
        if value == 10 then
            finish()
            feeds, gap, previous = feeds + 1, '', nil
        elseif space(value) and not first then
            gap = gap .. text:sub(i, after - 1)
        elseif space(value) then
            finish()
            gap, previous = text:sub(i, after - 1), nil
        else
            local join = first and (mark(value) or previous == ZWJ or CLOSE[value] or OPEN[previous]
                or not (wide(value) or wide(previous)))
            if join then last = after - 1
            else
                if first then finish() end
                first, last = i, after - 1
            end
            previous = value
        end
        i = after
    end
    finish()
    return list
end

-- Splits text into lines no wider than `width`, where measure(s) is the
-- drawn width of s. Lines break at spaces, and between CJK characters except
-- before closing or after opening punctuation. A piece wider than a whole
-- line breaks between characters. Spaces at a break are dropped.
function M.wrap(text, width, measure)
    local lines, line = {}, ''
    for _, piece in ipairs(pieces(text)) do
        local value = text:sub(piece[1], piece[2])
        for _ = 1, piece[4] do
            lines[#lines + 1] = line
            line = ''
        end
        local candidate = line == '' and value or line .. piece[3] .. value
        if measure(candidate) <= width then line = candidate
        else
            if line ~= '' then lines[#lines + 1] = line end
            if measure(value) <= width then line = value
            else
                line = ''
                local edges = M.boundaries(value)
                for k = 1, #edges - 1 do
                    local glyph = value:sub(edges[k], edges[k + 1] - 1)
                    if measure(line .. glyph) <= width then line = line .. glyph
                    else
                        assert(line ~= '', 'Text column too narrow')
                        lines[#lines + 1] = line
                        line = glyph
                    end
                end
            end
        end
    end
    if line ~= '' then lines[#lines + 1] = line end
    return lines
end

-- '{name}' placeholders are replaced by values.name; unknown names stay.
function M.format(text, values)
    return (text:gsub('{([%a_][%w_]*)}', function(name)
        local value = values[name]
        if value ~= nil then return tostring(value) end
    end))
end

-- Sorted placeholder names, to compare a translation with its English text.
function M.placeholders(text)
    local names = {}
    for name in text:gmatch('{([%a_][%w_]*)}') do names[#names + 1] = name end
    table.sort(names)
    return concat(names, ',')
end

-- Pseudo-translation for layout tests: accented letters the game's Latin
-- fonts carry (Latin-1 and Polish), 40% longer and bracketed, so clipped,
-- cut or untranslated text is easy to spot. Placeholders stay intact.
local PSEUDO = {a = 0xE1, c = 0xE7, d = 0xF0, e = 0xE9, i = 0xED, l = 0x142, n = 0xF1, o = 0xF6, s = 0x15B,
    u = 0xFC, y = 0xFD, z = 0x17C, A = 0xC1, C = 0xC7, D = 0xD0, E = 0xC9, I = 0xCD, L = 0x141, N = 0xD1,
    O = 0xD6, S = 0x15A, U = 0xDC, Y = 0xDD, Z = 0x17B}
function M.pseudo(text)
    local parts, i, n = {}, 1, #text
    while i <= n do
        local name = text:match('^{[%a_][%w_]*}', i)
        if name then
            parts[#parts + 1] = name
            i = i + #name
        else
            local c = text:sub(i, i)
            parts[#parts + 1] = PSEUDO[c] and M.encode(PSEUDO[c]) or c
            i = i + 1
        end
    end
    return '[' .. concat(parts) .. ' ' .. string.rep('~', math.max(2, math.ceil(M.length(text) * 0.4))) .. ']'
end

-- The shared table (see the top of this file), created on first use. Another
-- copy, a pack add-on or a stray assignment may have left it incomplete: the
-- fields every reader needs are filled in instead of failing in every mod.
function M.registry()
    local registry = rawget(_G, 'BingusTranslations')
    if type(registry) ~= 'table' then
        registry = {}
        rawset(_G, 'BingusTranslations', registry)
    end
    if type(rawget(registry, 'version')) ~= 'number' then rawset(registry, 'version', 1) end
    if type(rawget(registry, 'serial')) ~= 'number' then rawset(registry, 'serial', 0) end
    if type(rawget(registry, 'packs')) ~= 'table' then rawset(registry, 'packs', {}) end
    return registry
end

-- A language tag a pack may carry: 'de', 'pt-BR', 'zh-Hant', 'es-419', 'pseudo'.
local function valid_tag(tag)
    return type(tag) == 'string' and #tag <= 16 and tag:match('^%a%a%a?%-?[%w%-]*$') ~= nil
end

-- Adds a translation pack. Pack add-ons do the same inline, without this file
-- (translations.py writes that code); keep the two identical. A pack forces its
-- language on every mod only with force = true (any other value does not).
function M.register(pack)
    assert(type(pack) == 'table' and valid_tag(pack.language) and type(pack.mods) == 'table',
        'A translation pack needs a language tag and a mods table')
    local registry = M.registry()
    registry.packs[#registry.packs + 1] = pack
    if pack.force == true then registry.override = pack.language end
    registry.serial = registry.serial + 1
end

-- The game's Text Language (Options menu), which can differ from Steam's.
-- Build 25480438: the settings object [game.dll+0x3326340] + 705500 (what the
-- settings save 0x102f7a0 writes) holds at +212 an index into the table of
-- 15 language records at game.dll+0x37C5650; each record has its code string
-- at +8. Unreadable or implausible values mean "unknown", never a guess.
M.GAME = {settings = 0x2ce1508, index = 705628 + 212, table = 0x3180DE0, count = 15}
-- Record codes to BCP 47 tags. Only 'us' is confirmed (English); the others
-- are the spellings the game's code tables use. An unlisted code is kept
-- as its own tag, so no translation matches it and English shows.
M.GAME_CODES = {us = 'en', en = 'en', ['en-US'] = 'en', uk = 'en-GB', gb = 'en-GB', ['en-GB'] = 'en-GB',
    de = 'de', fr = 'fr', it = 'it', es = 'es', ['es-ES'] = 'es', mx = 'es-419', ['es-MX'] = 'es-419',
    ['es-419'] = 'es-419', pl = 'pl', ru = 'ru', jp = 'ja', ja = 'ja', kr = 'ko', ko = 'ko', br = 'pt-BR',
    ['pt-BR'] = 'pt-BR', pt = 'pt', ['zh-CN'] = 'zh-Hans', cn = 'zh-Hans', zh = 'zh-Hans', zhs = 'zh-Hans',
    ['zh-TW'] = 'zh-Hant', tw = 'zh-Hant', zht = 'zh-Hant', cz = 'cs', cs = 'cs', gr = 'el', el = 'el',
    nl = 'nl', tr = 'tr', ua = 'uk'}

local function number(bytes)
    local value = 0
    for k = #bytes, 1, -1 do value = value * 256 + byte(bytes, k) end
    return value
end

-- The code of the game's Text Language, read through the mod's own
-- read(address, size) (a ReadProcessMemory wrapper: bad addresses fail, never
-- crash), which receives addresses as Lua numbers. `game` is game.dll's base
-- address, a number or a pointer. Five reads.
function M.game_code(read, game)
    if type(game) == 'cdata' then
        local ok, value = pcall(function() return tonumber(require('ffi').cast('uintptr_t', game)) end)
        game = ok and value or nil
    end
    if type(game) ~= 'number' then return nil end
    local function load(address, size)
        local ok, bytes = pcall(read, address, size)
        if ok and type(bytes) == 'string' and #bytes == size then return bytes end
    end
    local function pointer(address)
        local bytes = load(address, 8)
        local value = bytes and number(bytes)
        if value and value >= 65536 and value < 2 ^ 47 then return value end
    end
    local g = M.GAME
    local settings = pointer(game + g.settings)
    local index = settings and load(settings + g.index, 4)
    index = index and number(index)
    if not index or index >= g.count then return nil end
    local record = pointer(game + g.table + 8 * index)
    local text = record and pointer(record + 8)
    local bytes = text and (load(text, 16) or load(text, 8))
    local code = bytes and bytes:match('^(%a[%a%-]*)%z')
    if code and #code <= 12 then return code end
end

-- Records the game's Text Language for every mod. A mod that can read game
-- memory calls this at start, and again when it sees the native font change.
-- Returns the tag and the game's code, or nil when the setting is unreadable.
function M.observe(read, game)
    local code = M.game_code(read, game)
    if not code then return nil end
    local tag = M.GAME_CODES[code] or code
    local registry = M.registry()
    if registry.game_language ~= tag then
        registry.game_language, registry.game_code = tag, code
        registry.serial = registry.serial + 1
    end
    return tag, code
end

-- Steam language names (ISteamApps::GetCurrentGameLanguage), as the game's
-- own Localization module reads them, to BCP 47 tags.
M.STEAM = {english = 'en', schinese = 'zh-Hans', tchinese = 'zh-Hant', koreana = 'ko', japanese = 'ja',
    russian = 'ru', polish = 'pl', french = 'fr', german = 'de', italian = 'it', spanish = 'es',
    latam = 'es-419', brazilian = 'pt-BR', portuguese = 'pt', ukrainian = 'uk', czech = 'cs', dutch = 'nl',
    turkish = 'tr', thai = 'th', vietnamese = 'vi', danish = 'da', finnish = 'fi', norwegian = 'no',
    swedish = 'sv', hungarian = 'hu', romanian = 'ro', bulgarian = 'bg', greek = 'el', arabic = 'ar',
    indonesian = 'id'}

-- Steam's current game language, which the game starts from until the player
-- picks a Text Language. Made once per session and only when the game's own
-- setting is unreadable: two lookups in steam_api64.dll, which the game has
-- already loaded (nothing is loaded), and two calls into it.
function M.steam_language()
    local ok, name = pcall(function()
        local ffi = require('ffi')
        -- Declared once per process, whichever copy of this file comes first,
        -- under this file's own names (asm labels): no mod's declaration of
        -- the same Windows functions can clash with these.
        if not pcall(ffi.typeof, 'bingus_steam_apps_fn') then
            ffi.cdef[[
                typedef void *(*bingus_steam_apps_fn)(void);
                typedef const char *(*bingus_steam_language_fn)(void *apps);
                void *bingus_text_module(const char *name) __asm__("GetModuleHandleA");
                void *bingus_text_export(void *module, const char *name) __asm__("GetProcAddress");
            ]]
        end
        local steam = ffi.C.bingus_text_module('steam_api64.dll')
        if steam == nil then return nil end
        local apps_fn = ffi.C.bingus_text_export(steam, 'SteamAPI_SteamApps_v008')
        local language_fn = ffi.C.bingus_text_export(steam, 'SteamAPI_ISteamApps_GetCurrentGameLanguage')
        if apps_fn == nil or language_fn == nil then return nil end
        local apps = ffi.cast('bingus_steam_apps_fn', apps_fn)()
        if apps == nil then return nil end
        local value = ffi.cast('bingus_steam_language_fn', language_fn)(apps)
        return value ~= nil and ffi.string(value) or nil
    end)
    return ok and name or nil
end

-- The game's language: its Text Language setting when a mod observed it,
-- else Steam's game language.
function M.game_language()
    local registry = M.registry()
    if registry.game_language then return registry.game_language end
    if registry.steam_language == nil then
        local name = M.steam_language()
        registry.steam_language = name and (M.STEAM[name] or name) or false
    end
    return registry.steam_language or nil
end

-- The language mods show: a forced pack's, else the game's, else English.
-- Forcing is global: every mod on Bingus Text shows the forced language.
function M.language()
    local override = M.registry().override
    if valid_tag(override) then return override end
    return M.game_language() or 'en'
end

-- Tags tried for a language, least specific first: 'zh-Hant' tries 'zh',
-- then 'zh-Hant'. Keys missing from both show in English.
local function chain(language)
    local base = language:match('^([^-]+)-')
    return base and {base, language} or {language}
end

local translator = {}
translator.__index = translator
translator.__call = function(self, key, values) return self:text(key, values) end

-- A translator for one mod. `english` is the mod's locales/en.lua table:
-- {mod = 'mod_id', language = 'en', strings = {key = text},
-- limits = {key = characters}, multiline = {key = true}}; `bundled` maps
-- language tags to the other locale files shipped in the mod; log(message)
-- receives rejected entries and one summary line per language.
function M.new(english, bundled, log)
    assert(type(english) == 'table' and type(english.strings) == 'table', 'English texts required')
    local mod = english.mod
    assert(type(mod) == 'string' and mod:match('^[%l%d_]+$'), 'Invalid mod id')
    local limits, multiline = english.limits or {}, english.multiline or {}
    for key, text in pairs(english.strings) do
        assert(type(key) == 'string' and key:match('^[%w_.%-]+$'), 'Invalid text key')
        assert(M.check(text, multiline[key]), 'Invalid English text: ' .. key)
        assert(not limits[key] or M.length(text) <= limits[key], 'English text over its limit: ' .. key)
    end
    return setmetatable({mod = mod, english = english.strings, limits = limits, multiline = multiline,
        bundled = bundled or {}, log = log, logged = {}}, translator)
end

function translator:warn(message)
    if self.log and not self.logged[message] then
        self.logged[message] = true
        self.log(message)
    end
end

-- Copies the valid entries of one source over `texts` and marks them in
-- `translated`. Invalid entries keep the text they would have replaced.
function translator:merge(texts, translated, source, origin)
    if type(source) ~= 'table' then return end
    for key, text in pairs(source) do
        local english = self.english[key]
        local ok, why = english ~= nil, 'unknown key'
        if ok then ok, why = M.check(text, self.multiline[key]) end
        if ok and M.placeholders(text) ~= M.placeholders(english) then ok, why = nil, 'placeholders differ from English' end
        if ok and self.limits[key] and M.length(text) > self.limits[key] then
            ok, why = nil, 'longer than ' .. self.limits[key] .. ' characters'
        end
        if ok then
            texts[key], translated[key] = text, true
        else
            self:warn('translation ' .. origin .. ': ' .. tostring(key) .. ': ' .. why)
        end
    end
end

function translator:resolve(language, registry)
    local texts = {}
    for key, text in pairs(self.english) do texts[key] = text end
    if language == 'pseudo' then
        for key, text in pairs(texts) do texts[key] = M.pseudo(text) end
    elseif language ~= 'en' then
        local translated = {}
        for _, tag in ipairs(chain(language)) do
            local bundled = self.bundled[tag]
            self:merge(texts, translated, bundled and bundled.strings, tag .. ' (bundled)')
            for _, pack in ipairs(registry.packs) do
                -- A malformed entry (another copy's or add-on's) is skipped, never indexed blindly.
                if type(pack) == 'table' and pack.language == tag and type(pack.mods) == 'table' then
                    self:merge(texts, translated, pack.mods[self.mod], tag .. ' (' .. tostring(pack.name) .. ')')
                end
            end
        end
        local count, total = 0, 0
        for key in pairs(self.english) do
            total = total + 1
            if translated[key] then count = count + 1 end
        end
        self:warn('language ' .. language .. ': ' .. count .. ' of ' .. total .. ' texts translated')
    end
    self.texts, self.language, self.serial = texts, language, registry.serial
    self.generation = (self.generation or 0) + 1
end

-- Resolves again when the language or the installed packs changed. Returns
-- true when it did. Every lookup does this too (a menu host may call a mod's
-- text function at any time), so a mod that caches what it drew compares
-- tr.generation, which grows with every resolution, not this return value.
function translator:refresh()
    local registry = M.registry()
    local language = M.language()
    if self.texts and self.serial == registry.serial and self.language == language then return false end
    self:resolve(language, registry)
    return true
end

-- The text for `key` in the current language, placeholders filled from
-- `values`.
function translator:text(key, values)
    self:refresh()
    local text = self.texts[key]
    if text == nil then error('Unknown text key: ' .. tostring(key), 2) end
    return values and M.format(text, values) or text
end

-- Keep this rarely run code interpreted: it must not add traces to the
-- game's shared LuaJIT code cache.
if jit and jit.off then
    for _, fn in ipairs({M.decode, M.encode, M.check, M.display, M.length, upper_value, M.upper, M.clip, mark,
                         wide, space, M.boundaries, pieces, M.wrap, M.format, M.placeholders, M.pseudo,
                         M.registry, valid_tag, M.register, number, M.game_code, M.observe, M.steam_language,
                         M.game_language, M.language, chain, M.new, translator.warn, translator.merge,
                         translator.resolve, translator.refresh, translator.text}) do
        jit.off(fn, true)
    end
end

return M
end)(),
    locales = {bundled = {}}}
mom_text.locales.en = (function()
-- Mod Options Menu: English texts, the source of every translation.
-- Translators: see TRANSLATING.md. Option names, descriptions and choices come
-- from the mods that register them and are translated with those mods.
return {
    mod = 'mod_options_menu',
    title = 'Mod Options Menu',
    language = 'en',
    strings = {
        -- The fourth tab of the escape menu, after the game's GAME, SOCIAL and OPTIONS.
        -- Upper case like theirs, and about as short.
        ['tab.mods'] = 'MODS',
        -- The first category button of the MODS tab when no mod has registered options.
        ['category.none'] = 'NO MOD OPTIONS INSTALLED',
        -- Category name for a mod that registered options without giving its name.
        ['mod.unnamed'] = 'MODS',
        -- The last category button when more than 8 mods have options: the
        -- buttons then show 7 mods at a time, and this one opens the page row
        -- below. {page} and {pages} are numbers. Upper case like the buttons.
        ['category.page'] = 'PAGE {page} OF {pages}',
        -- That button's only row: its name, its value for each page ({page}
        -- and {pages} are numbers) and its description.
        ['page.label'] = 'Mods Page',
        ['page.value'] = '{page} / {pages}',
        ['page.description'] = 'The category buttons show 7 mods at a time. Change the page to see the others.',
    },
    -- Rough room in ems (the tool warns when a translation looks wider).
    widths = {['tab.mods'] = 8, ['category.none'] = 20, ['category.page'] = 20},
}
end)()
local mom_files = {}
mom_files.api = function(...)
-- The API other mods use; src/mod_options_menu.lua publishes it as the global
-- ModOptionsMenu.
local mom = ...
local state, note, translation = mom.state, mom.note, mom.translation
local display_text, saved_values, encode, decode = mom.display_text, mom.saved_values, mom.encode, mom.decode
local snap, valid_value, set_pending = mom.snap, mom.valid_value, mom.set_pending
local new_option, same_option, descriptor = mom.new_option, mom.same_option, mom.descriptor
local MAX_MODS, MAX_ROWS, SAVE_DELAY = mom.MAX_MODS, mom.MAX_ROWS, mom.SAVE_DELAY

-- Names a caller's mod after its addon entry, e.g.
-- 'mods/example/better_hud' -> 'BETTER HUD', for authors who pass no mod name.
local function caller_mod()
    for level = 3, 8 do
        local info = debug.getinfo(level, 'S')
        if not info then break end
        local entry = info.source and info.source:match('mods/[%w_]+/([%w_/]+)')
        if entry then
            local name = display_text((entry:match('([%w_]+)$') or entry):gsub('_', ' '))
            if name ~= '' then return name end
        end
    end
    return translation.tr('mod.unnamed')
end

-- Categories ------------------------------------------------------------------

-- A mod is known by the mod_id it gives, else by the addon that registers (the
-- chunk of its code) and the mod name resolved at its first registration. A
-- later registration of that addon finds the category by that name, by the
-- name shown now, or by the first registration's text function returning that
-- name now, so a mod whose name follows the game's language keeps one
-- category. Shown names follow the language (translation.refresh); identity
-- never does.
local OWN_SOURCE = debug.getinfo(1, 'S').source
local function caller_source()
    for level = 2, 40 do
        local info = debug.getinfo(level, 'S')
        if not info then break end
        if info.what ~= 'C' and info.source ~= OWN_SOURCE then return info.source end
    end
    return '?'
end

-- A namespaced id such as 'author.mod_name': letters, digits and _ . - / :
local function valid_mod_id(mod_id)
    return type(mod_id) == 'string' and #mod_id <= 64 and mod_id:find('^[%w_%.%-/:]+$') ~= nil
end

local function same_mod(mod, mod_id, origin, title)
    if mod_id or mod.id then return mod.id == mod_id end
    if mod.origin ~= origin then return false end
    if mod.name == title or mod.title == title then return true end
    local current = type(mod.source) == 'function' and translation.resolve(mod.source, 40)
    return current and translation.T.upper(current) == title or false
end

local function describe_mod(mod)
    return mod.id and ("mod_id '" .. mod.id .. "'") or ('addon ' .. mod.origin:gsub('^[@=]', ''))
end

-- Two mods may show the same name: they keep their own categories, and the
-- log says so once, when the second registers.
local function warn_same_title(mod)
    for _, other in ipairs(state.mods) do
        if other.title == mod.title then
            note('Two mod categories are named ' .. mod.title .. ': ' .. describe_mod(mod) .. ' is kept apart from '
                 .. describe_mod(other) .. '.')
            return
        end
    end
end

-- The MODS tab shows the first MAX_MODS mods to register (src/view.lua: past
-- 8, in pages). Another mod is refused, so its author learns it is not shown;
-- each refused mod is logged once, the first LOGGED_REFUSALS of them.
local LOGGED_REFUSALS = 8
local FULL = 'all ' .. MAX_MODS .. ' mod categories are in use'
local function refuse_mod(key, title)
    local count = state.refused_count
    if count < LOGGED_REFUSALS and not state.refused[key] then
        state.refused[key], state.refused_count = true, count + 1
        note('Refused the options of ' .. title .. ': ' .. FULL
             .. (count + 1 == LOGGED_REFUSALS and '; further refused mods are not logged.' or '.'))
    end
    return false, FULL
end

-- The category of the mod a registration names, new while a button is free.
local function category(mod_id, title, source)
    local origin = not mod_id and caller_source() or nil
    for _, mod in ipairs(state.mods) do
        if same_mod(mod, mod_id, origin, title) then return mod end
    end
    if #state.mods >= MAX_MODS then return refuse_mod(mod_id or (origin .. '\0' .. title), title) end
    local mod = {id = mod_id, origin = origin, name = title, title = title, source = source, order = {},
                 sequence = #state.mods + 1}
    warn_same_title(mod)
    state.mods[mod.sequence] = mod
    return mod
end

-- API -------------------------------------------------------------------------

-- The option a registration describes and the mod name it gives (false when
-- none), or nil and the reason it is refused.
local function checked(id, spec)
    if type(id) ~= 'string' or id == '' or #id > 96 or id:find('[%c]') or type(spec) ~= 'table'
       or not translation.resolve(spec.label, 64) then
        return nil, 'invalid option registration'
    end
    local mod_name = spec.mod ~= nil and translation.resolve(spec.mod, 40)
    if spec.mod ~= nil and not mod_name then return nil, 'invalid mod name' end
    if spec.mod_id ~= nil and not valid_mod_id(spec.mod_id) then return nil, 'invalid mod_id' end
    local option, reason = new_option(id, spec)
    if not option then return nil, reason end
    return option, mod_name
end

-- Version 2 (v1.1): texts may be functions; limits count characters.
-- Version 3: register_option refuses a mod past max_mods (112: past 8 mods
-- the category buttons show them in pages); spec.mod_id.
local api = {api = 1, version = 3, max_mods = MAX_MODS, max_options = MAX_ROWS}
-- id: stable unique string that keys the saved value. spec: {type = 'toggle'
-- | 'choice' | 'slider', label = 'Row text', mod = 'Mod name', mod_id =
-- 'author.mod', default = ..., choices = {...} (choice), min/max/step
-- (slider), gap = true (space above), description = 'Shown beside the rows
-- while the option is selected'}. mod_id (preferred) keeps a mod's options in
-- one category whatever its shown name. label, mod, description and each
-- choice may be a function returning the text in the current language (see
-- translation.refresh). Limits in characters: label 64, mod 40, choice 48,
-- description 400; mod_id 64.
function api.register_option(id, spec)
    local option, detail = checked(id, spec)
    if not option then return false, detail end
    local existing = state.options[id]
    if existing then
        if same_option(existing, option) then return true end
        return false, 'option already registered differently'
    end
    -- The category is named after the mod's name as first registered.
    local mod, refusal = category(spec.mod_id, translation.T.upper(detail or caller_mod()), spec.mod)
    if not mod then return false, refusal end
    if #mod.order >= MAX_ROWS then return false, 'mod already has ' .. MAX_ROWS .. ' options' end
    local title = mod.title
    state.option_count = state.option_count + 1
    option.mod, option.sequence = title, state.option_count
    option.descriptor, option.descriptor_block = descriptor(option)
    mod.order[#mod.order + 1] = option
    state.options[id] = option
    local saved = saved_values()[id]
    local value = saved and decode(option, saved)
    if value == nil then value = option.default end
    state.values[id] = value
    state.revision = state.revision + 1
    note('Registered option ' .. id .. ' (' .. option.kind .. ') under ' .. title .. '.')
    return true
end

-- Applied value: boolean (toggle), 1-based choice index (choice) or number
-- (slider). A player's edit counts once applied.
function api.get(id)
    return state.values[id]
end

-- Sets a value from code, replacing any unapplied player edit of it;
-- on_change callbacks are not called. The value counts at once. set() writes
-- no row itself: another mod's update may call it after the escape menu has
-- closed (its screen freed) and before MOM's next step notices, so a row of
-- the MODS view shows the value from the next step that has checked the view.
function api.set(id, value)
    local option = state.options[id]
    if not option then return false, 'unknown option' end
    if option.kind == 'slider' and type(value) == 'number' then value = snap(option, value) end
    if not valid_value(option, value) then return false, 'invalid value' end
    state.values[id] = value
    set_pending(id, nil)
    -- An unchanged value leaves the values file alone.
    local text, saved = encode(option, value), saved_values()
    if saved[id] ~= text then saved[id], state.dirty, state.save_timer = text, true, SAVE_DELAY end
    -- MCM confirms through this API while MOM's native view/update is suspended.
    -- Persist DBF confirmations here instead of relying on that update timer.
    if id:sub(1,24)=='native_stratagem_radial.' then
        mom.save_values()
        if state.save_failed then return false,'Cannot save DBF settings' end
    end
    if state.view then state.queued[id], state.queued_any = true, true end
    return true
end

-- callback(value, id) runs when the player applies a change to the option.
function api.on_change(id, callback)
    if type(id) ~= 'string' or type(callback) ~= 'function' then return false, 'invalid callback' end
    local list = state.callbacks[id] or {}
    list[#list + 1] = callback
    state.callbacks[id] = list
    return true
end

function api.ready() return state.native ~= nil end

mom.api = api
end
mom_files.bingus_memory = function(...)
-- bingus_memory.lua, version 1: the read side of Bingus Shared Runtime.
-- Canonical copy: github.com/CowboyBingus/BingusSharedRuntime, runtime/bingus_memory.lua.
--
-- Loading: the chunk returns {VERSION = 1, new = function(runtime)} and
-- installs nothing. A mod vendors a byte-identical copy next to
-- bingus_runtime.lua and runs each file once when it loads:
--   local runtime = <bingus_runtime.lua>
--   local memory = <bingus_memory.lua>.new(runtime)   -- the api below
--   <bingus_write.lua>.extend(memory)                 -- optional: checked writes
-- This file only reads memory, page information and module files; it never
-- changes memory or page protection. A mod whose build refuses sources that can
-- modify memory vendors bingus_runtime.lua and this file only.
--
-- Windows functions are declared under private, versioned FFI names
-- (bingus_memory1_*, each with an __asm__ label naming the real export), at
-- most once per version in the whole game. ffi.cdef keeps the first prototype
-- of a name for the whole game, so a plain name would bind to whatever another
-- mod declared first. Copies of other versions declare their own names.
--
-- memory.new(runtime) -> api. runtime is the table bingus_runtime.lua returns:
-- its shared table keeps module hashes for the session. Each api has its own
-- buffers and counters; every api of one copy shares the bound functions.
--   api.read(address, size)        the bytes as a string, or nil when they cannot
--                                  all be read; allocates only that string
--   api.read_into(address, size, buffer)  into a buffer the caller keeps: true or
--                                  false, no allocation
--   api.pointer(bytes [, offset])  the user-mode pointer stored little-endian at
--                                  bytes[offset+1 .. offset+8], as uint8_t *, or nil
--   api.address(pointer)           a pointer, number or integer cdata as a Lua number
--   api.distance(a, b)             api.address(a) - api.address(b)
--   api.writable_data(address, size)  true when [address, address + size) is
--                                  committed private read-write memory: never code,
--                                  read-only, guard or module image pages
--   api.queries                    page queries made so far (one per memory region)
--   api.time()                     seconds from the performance counter (a Lua number)
--   api.module([name])             a loaded module's base as uint8_t *, or nil;
--                                  no name: the executable
--   api.module_hash(module)        SHA-256 (uppercase hex) of the module's file, read
--                                  once per session for every mod (BingusRuntime.hashes)
--   api.verify_build(build)        build = {exe_sha256, game_sha256}: true, or false and why
--   api.windows                    {ffi, kernel32, bcrypt}: the bound functions under
--                                  their Windows names, for calls the api does not cover
-- Addresses are pointer cdata (read, read_into) or pointers, numbers and integer
-- cdata (address, distance, writable_data).
--
-- Cost per call: read and read_into one ReadProcessMemory (about 1-2 us in game);
-- writable_data one VirtualQuery per memory region in the range (about 0.29 ms
-- each in game), so check only on frames that act; time() one
-- QueryPerformanceCounter (unmeasured in game). read_into, address, distance,
-- writable_data and time allocate nothing, interpreted or compiled.
local memory = {VERSION = 1}

local type, error, pcall, tonumber, ipairs, pairs = type, error, pcall, tonumber, ipairs, pairs
local max, format, concat = math.max, string.format, table.concat

local HIGH = 4294967296
local MEM_COMMIT, MEM_PRIVATE, PAGE_READWRITE = 0x1000, 0x20000, 4

-- Windows functions ----------------------------------------------------------------

-- The region record is MEMORY_BASIC_INFORMATION with each 64-bit field read as
-- two 32-bit halves, and the cell turns a pointer into two halves through one
-- union (one base, so compiled code sees the store): neither allocates when read.
-- The region record is also this file's sentinel: once it exists, every
-- declaration below exists too.
local PREFIX = 'bingus_memory1_'
local SENTINEL = 'bingus_memory1_region'
local DECLARATIONS = [[
    typedef struct bingus_memory1_region {
        uint32_t base_low, base_high, allocation_base_low, allocation_base_high;
        uint32_t allocation_protection; uint16_t partition, reserved;
        uint32_t size_low, size_high, state, protection, type, padding;
    } bingus_memory1_region;
    typedef union bingus_memory1_cell {
        const void *pointer;
        struct { uint32_t low, high; };
    } bingus_memory1_cell;
    void *bingus_memory1_GetModuleHandleA(const char *name) __asm__("GetModuleHandleA");
    uint32_t bingus_memory1_GetModuleFileNameW(void *module, uint16_t *path, uint32_t capacity) __asm__("GetModuleFileNameW");
    void *bingus_memory1_GetCurrentProcess(void) __asm__("GetCurrentProcess");
    int bingus_memory1_ReadProcessMemory(void *process, const void *address, void *buffer, size_t size,
                                         size_t *done) __asm__("ReadProcessMemory");
    uint32_t bingus_memory1_VirtualQuery(uint64_t address, bingus_memory1_region *region, size_t size) __asm__("VirtualQuery");
    int bingus_memory1_QueryPerformanceCounter(uint32_t *count) __asm__("QueryPerformanceCounter");
    int bingus_memory1_QueryPerformanceFrequency(uint32_t *frequency) __asm__("QueryPerformanceFrequency");
    void *bingus_memory1_CreateFileW(const uint16_t *path, uint32_t access, uint32_t share, void *security,
                                     uint32_t disposition, uint32_t flags, void *template_file) __asm__("CreateFileW");
    int bingus_memory1_ReadFile(void *file, void *buffer, uint32_t size, uint32_t *done, void *overlapped) __asm__("ReadFile");
    int bingus_memory1_CloseHandle(void *handle) __asm__("CloseHandle");
    int32_t bingus_memory1_BCryptOpenAlgorithmProvider(void **algorithm, const uint16_t *name, const uint16_t *provider,
                                                       uint32_t flags) __asm__("BCryptOpenAlgorithmProvider");
    int32_t bingus_memory1_BCryptCloseAlgorithmProvider(void *algorithm, uint32_t flags) __asm__("BCryptCloseAlgorithmProvider");
    int32_t bingus_memory1_BCryptCreateHash(void *algorithm, void **hash, void *object, uint32_t object_size,
                                            const void *secret, uint32_t secret_size, uint32_t flags) __asm__("BCryptCreateHash");
    int32_t bingus_memory1_BCryptHashData(void *hash, const void *data, uint32_t size, uint32_t flags) __asm__("BCryptHashData");
    int32_t bingus_memory1_BCryptFinishHash(void *hash, void *digest, uint32_t size, uint32_t flags) __asm__("BCryptFinishHash");
    int32_t bingus_memory1_BCryptDestroyHash(void *hash) __asm__("BCryptDestroyHash");
]]
local FUNCTIONS = {
    kernel32 = {'GetModuleHandleA', 'GetModuleFileNameW', 'GetCurrentProcess', 'ReadProcessMemory', 'VirtualQuery',
                'QueryPerformanceCounter', 'QueryPerformanceFrequency', 'CreateFileW', 'ReadFile', 'CloseHandle'},
    bcrypt = {'BCryptOpenAlgorithmProvider', 'BCryptCloseAlgorithmProvider', 'BCryptCreateHash',
              'BCryptHashData', 'BCryptFinishHash', 'BCryptDestroyHash'},
}

local bound, ticks_per_second
-- {ffi, kernel32, bcrypt}, each library table holding the functions above under
-- their Windows names. Declared at most once per version in the whole game.
local function bind()
    if bound then return bound end
    local ffi = require('ffi')
    if not ffi.abi('64bit') then error('Windows x64 is required', 0) end
    if not pcall(ffi.typeof, SENTINEL) then ffi.cdef(DECLARATIONS) end
    local result = {ffi = ffi}
    for library, names in pairs(FUNCTIONS) do
        local loaded, functions = ffi.load(library), {}
        for _, name in ipairs(names) do functions[name] = loaded[PREFIX .. name] end
        result[library] = functions
    end
    local frequency = ffi.new('uint32_t[2]')
    if result.kernel32.QueryPerformanceFrequency(frequency) == 0 then error('performance counter unavailable', 0) end
    ticks_per_second = frequency[0] + frequency[1] * HIGH
    bound = result
    return bound
end

-- Module files ---------------------------------------------------------------------

-- SHA-256 (uppercase hex) of the file at path (a UTF-16 string buffer).
local function sha256(windows, path)
    local ffi, kernel, bcrypt = windows.ffi, windows.kernel32, windows.bcrypt
    local file = kernel.CreateFileW(path, 0x80000000, 7, nil, 3, 0x08000000, nil)
    if file == ffi.cast('void *', -1) then error('cannot read the module file', 0) end
    local algorithm, hash = ffi.new('void *[1]'), ffi.new('void *[1]')
    local ok, result = pcall(function()
        local id = ffi.new('uint16_t[7]', {83, 72, 65, 50, 53, 54, 0})  -- "SHA256"
        if bcrypt.BCryptOpenAlgorithmProvider(algorithm, id, nil, 0) ~= 0 then error('SHA-256 unavailable', 0) end
        if bcrypt.BCryptCreateHash(algorithm[0], hash, nil, 0, nil, 0, 0) ~= 0 then
            error('SHA-256 unavailable', 0)
        end
        local buffer, count = ffi.new('uint8_t[1048576]'), ffi.new('uint32_t[1]')
        while true do
            if kernel.ReadFile(file, buffer, 1048576, count, nil) == 0 then error('module file read failed', 0) end
            if count[0] == 0 then break end
            if bcrypt.BCryptHashData(hash[0], buffer, count[0], 0) ~= 0 then error('SHA-256 failed', 0) end
        end
        local digest, hex = ffi.new('uint8_t[32]'), {}
        if bcrypt.BCryptFinishHash(hash[0], digest, 32, 0) ~= 0 then error('SHA-256 failed', 0) end
        for i = 0, 31 do hex[i + 1] = format('%02X', digest[i]) end
        return concat(hex)
    end)
    if hash[0] ~= nil then bcrypt.BCryptDestroyHash(hash[0]) end
    if algorithm[0] ~= nil then bcrypt.BCryptCloseAlgorithmProvider(algorithm[0], 0) end
    kernel.CloseHandle(file)
    if not ok then error(result, 0) end
    return result
end

-- The SHA-256 of a loaded module's file, read once per session for every mod:
-- kept in the shared table by file path.
local function module_hash(runtime, windows, module)
    local ffi = windows.ffi
    local path = ffi.new('uint16_t[32768]')
    local length = windows.kernel32.GetModuleFileNameW(module, path, 32768)
    if length == 0 or length >= 32768 then error('module file name unavailable', 0) end
    local shared = runtime.shared()
    local key = 'sha256:' .. ffi.string(path, length * 2)
    local cached = shared.hashes[key]
    if cached then return cached end
    local hex = sha256(windows, path)
    shared.hash_reads = shared.hash_reads + 1
    shared.hashes[key] = hex
    return hex
end

-- The api --------------------------------------------------------------------------

function memory.new(runtime)
    if type(runtime) ~= 'table' or type(runtime.shared) ~= 'function' then
        error('bingus_memory.lua: new(runtime) needs the table bingus_runtime.lua returns', 2)
    end
    runtime.shared()
    local windows = bind()
    local ffi, kernel = windows.ffi, windows.kernel32
    local read_memory, query, query_counter = kernel.ReadProcessMemory, kernel.VirtualQuery,
        kernel.QueryPerformanceCounter
    local process = kernel.GetCurrentProcess()
    -- ReadProcessMemory reports its count as a 64-bit size: it is read back as two
    -- 32-bit words, because reading the 64-bit value boxes a new cdata in
    -- interpreted code. Only the call writes this buffer.
    local done = ffi.new('size_t[1]')
    local done32 = ffi.cast('uint32_t *', done)
    local region, region_size = ffi.new(SENTINEL), ffi.sizeof(SENTINEL)
    local cell, counter = ffi.new('bingus_memory1_cell'), ffi.new('uint32_t[2]')
    local scratch_size = 256
    local scratch = ffi.new('uint8_t[?]', scratch_size)
    local ticks = ticks_per_second
    local api = {queries = 0, windows = windows}

    -- A pointer, number or integer cdata as a number, without allocating: a
    -- pointer passes through the cell. Exact below 2^53 (user-mode addresses
    -- end at 2^47).
    local function address_of(address)
        if type(address) == 'number' then return address end
        if type(address) == 'cdata' then
            local integer = tonumber(address)
            if integer then return integer end
        end
        cell.pointer = address
        return cell.low + cell.high * HIGH
    end

    function api.module(name)
        local handle = kernel.GetModuleHandleA(name)
        if handle == nil then return nil end
        return ffi.cast('uint8_t *', handle)
    end

    -- The bytes at address as a string, or nil when they cannot all be read.
    -- Allocates only the returned string.
    function api.read(address, size)
        if size > scratch_size then
            scratch_size = max(size, scratch_size * 2)
            scratch = ffi.new('uint8_t[?]', scratch_size)
        end
        if read_memory(process, address, scratch, size, done) == 0 or done32[0] ~= size then
            return nil
        end
        return ffi.string(scratch, size)
    end

    -- Into a buffer the caller keeps: no allocation at all.
    function api.read_into(address, size, buffer)
        return read_memory(process, address, buffer, size, done) ~= 0 and done32[0] == size
    end

    -- The user-mode pointer stored little-endian at bytes[offset+1 .. offset+8].
    function api.pointer(bytes, offset)
        offset = offset or 0
        if type(bytes) ~= 'string' or offset < 0 or offset + 8 > #bytes then return nil end
        local b1, b2, b3, b4, b5, b6, b7, b8 = bytes:byte(offset + 1, offset + 8)
        if b7 ~= 0 or b8 ~= 0 then return nil end
        local value = b1 + b2 * 256 + b3 * 65536 + b4 * 16777216 + (b5 + b6 * 256) * HIGH
        if value < 0x10000 or value >= 0x800000000000 then return nil end
        return ffi.cast('uint8_t *', value)
    end

    api.address = address_of

    function api.distance(first, second)
        return address_of(first) - address_of(second)
    end

    -- True when [address, address + size) is committed private read-write memory:
    -- never code, read-only, guard or module image pages. One VirtualQuery per
    -- region, each answered in the region record (no allocation).
    function api.writable_data(address, size)
        if type(size) ~= 'number' or size <= 0 then return false end
        local cursor = address_of(address)
        local finish = cursor + size
        while cursor < finish do
            api.queries = api.queries + 1
            if query(cursor, region, region_size) ~= region_size then return false end
            if region.state ~= MEM_COMMIT or region.type ~= MEM_PRIVATE or region.protection ~= PAGE_READWRITE then
                return false
            end
            local region_end = region.base_low + region.base_high * HIGH + region.size_low + region.size_high * HIGH
            if region_end <= cursor then return false end
            cursor = region_end
        end
        return true
    end

    -- Seconds since an arbitrary start (boot), from the performance counter read
    -- as two 32-bit halves into a reused buffer; the frequency is read once.
    function api.time()
        query_counter(counter)
        return (counter[0] + counter[1] * HIGH) / ticks
    end

    function api.module_hash(module)
        return module_hash(runtime, windows, module)
    end

    -- build: {exe_sha256, game_sha256}. true, or false and why.
    function api.verify_build(build)
        local exe, game = api.module(nil), api.module('game.dll')
        if not exe or not game then return false, 'game modules unavailable' end
        if api.module_hash(exe) ~= build.exe_sha256 or api.module_hash(game) ~= build.game_sha256 then
            return false, 'unsupported game build'
        end
        return true
    end

    return api
end

return memory
end
mom_files.bingus_runtime = function(...)
-- bingus_runtime.lua, version 1: the core of Bingus Shared Runtime.
-- Canonical copy: github.com/CowboyBingus/BingusSharedRuntime, runtime/bingus_runtime.lua.
--
-- Helldivers 2 runs the game and every Lua mod in one LuaJIT state, with one
-- global update chain. This file gives a mod the update guard every mod used
-- to write by hand, and the session table all runtime copies share. It uses no
-- FFI and no system function.
--
-- Loading: each runtime file is one chunk that returns a table and installs
-- nothing until the mod asks. A mod vendors byte-identical copies of the files
-- it needs and runs each once when it loads:
--   local runtime = <bingus_runtime.lua>              -- this file: shared(), guard()
--   local memory = <bingus_memory.lua>.new(runtime)   -- reads, page checks, module hashes, time()
--   <bingus_write.lua>.extend(memory)                 -- checked writes, added to memory
-- A mod that never touches memory vendors this file alone; one that only reads
-- vendors this file and bingus_memory.lua.
--
-- Copies of different versions can run in the same game. Their session state
-- lives in one global table, BingusRuntime = {hashes, statuses, versions,
-- hash_reads}, which every copy of every version shares.
--
-- runtime.shared([globals]) -> BingusRuntime, created or repaired.
-- runtime.guard(options) -> guard: the update and shutdown wrappers. The
-- previous update runs outside pcall, so its errors reach the game unchanged
-- (P1); the first failure survives shutdown as "stopped after: <reason>" (P2);
-- 8 errors stop the mod, counted per burst so rare transient errors never add
-- up (P3); a mod that can restore its state pauses after an error below it and
-- resumes when the updates below run cleanly again; every argument and return
-- value passes through; a status table per mod lands in BingusRuntime.statuses.
--
-- Per-frame cost of a guard: the mod's step under pcall, a few boolean tests
-- and stores and two integer counters around the previous update; no
-- allocation, closure or system call. Unmeasured in game.
local runtime = {VERSION = 1}

local type, pcall, error, tostring, rawget, rawset, ipairs = type, pcall, error, tostring, rawget, rawset, ipairs

-- Session state shared by every copy of every version ----------------------------

local SHARED = 'BingusRuntime'
local SHARED_TABLES = {'hashes', 'statuses', 'versions'}

-- Another copy, another version or another mod may have left the table
-- incomplete (even `BingusRuntime = {}`): missing or broken fields are filled in,
-- so one stray assignment cannot stop every mod on the runtime.
function runtime.shared(globals)
    globals = globals or _G
    local shared = rawget(globals, SHARED)
    if type(shared) ~= 'table' then
        shared = {}
        rawset(globals, SHARED, shared)
    end
    for _, field in ipairs(SHARED_TABLES) do
        if type(rawget(shared, field)) ~= 'table' then rawset(shared, field, {}) end
    end
    if type(rawget(shared, 'hash_reads')) ~= 'number' then rawset(shared, 'hash_reads', 0) end
    rawset(rawget(shared, 'versions'), runtime.VERSION, true)
    return shared
end

-- Update guard -----------------------------------------------------------------------

-- options:
--   name    key in BingusRuntime.statuses (required, one guard per name)
--   step    function(dt, ...) before the previous update, every frame while running
--   after   function() after the previous update returned, while running
--   stop    function(reason) once, when the guard stops or the game shuts down;
--           its errors are kept in status.stop_error, never raised
--   pause   function(reason), optional: an update below this mod raised; restore
--           the game state and reset the mod to a fresh start. With it the guard
--           pauses (no step, no after) and resumes once the updates below have
--           returned on `resume` frames in a row (default 60). Without it such an
--           error stops the guard. A pause that raises stops the guard.
--   log     function(line) for the guard's few lines (errors, pauses, resumes, stop)
--   errors  errors that stop the guard (default 8), counted separately for the
--           mod's own step and after and for the updates below it. A count starts
--           again after `clean` frames without such an error (default 3600, about a
--           minute at 60 FPS), so rare transient errors never add up to a stop.
--   env     the table holding update and shutdown (default _G)
-- guard.install() wraps env.update and env.shutdown and returns the guard.
-- guard.stop(reason) stops it from the mod (a refusal counts as the first failure).
-- guard.running() is true from install until a stop or shutdown.
-- guard.status: {name, version, state, installed, errors, lower_errors, pauses,
--   first_error, burst_error, first_failure, stop_error}; state is 'new', 'running',
--   'paused: <reason>', 'stopped: <reason>', then at shutdown 'stopped' or
--   'stopped after: <first failure>'.
function runtime.guard(options)
    local name = options.name
    if type(name) ~= 'string' or name == '' then error('guard name required', 0) end
    local shared = runtime.shared(options.env)
    if shared.statuses[name] and shared.statuses[name].installed then error('guard ' .. name .. ' already installed', 0) end
    local status = {name = name, version = runtime.VERSION, state = 'new', installed = false, errors = 0,
        lower_errors = 0, pauses = 0}
    shared.statuses[name] = status
    local step, after_step, stop_work, pause_work, log = options.step, options.after, options.stop, options.pause,
        options.log
    local limit, resume_after, clean_after = options.errors or 8, options.resume or 60, options.clean or 3600
    local previous_update, previous_shutdown
    local in_previous, stopped, paused, failed = false, false, false, false
    local clean_run, lower_run = 0, 0

    local function note(line)
        if log then pcall(log, line) end
    end

    local function halt(reason)
        if stopped then return end
        stopped, paused = true, false
        status.first_failure = status.first_failure or reason
        status.state = 'stopped: ' .. reason
        note(name .. ' stopped: ' .. reason)
        if stop_work then
            local ok, why = pcall(stop_work, reason)
            if not ok then status.stop_error = tostring(why) end
        end
    end

    -- The mod's own step or after raised: one log line per burst of errors.
    local function failed_step(problem)
        failed, clean_run = true, 0
        status.errors = status.errors + 1
        local text = tostring(problem)
        status.first_error = status.first_error or text
        if status.errors == 1 then
            status.burst_error = text
            note(name .. ' error: ' .. text)
        end
        if status.errors >= limit then halt('stopped after ' .. limit .. ' errors: ' .. status.burst_error) end
    end

    -- An update below this mod raised (seen on the next frame).
    local function failed_below()
        lower_run = 0
        status.lower_errors = status.lower_errors + 1
        if not pause_work then return halt('the previous update failed') end
        if status.lower_errors >= limit then
            return halt('stopped after ' .. limit .. ' failed updates below this mod')
        end
        if paused then return end
        paused = true
        status.pauses = status.pauses + 1
        status.state = 'paused: the previous update failed'
        note(name .. ' paused: the previous update failed')
        local ok, why = pcall(pause_work, 'the previous update failed')
        if not ok then halt('pause failed: ' .. tostring(why)) end
    end

    local function resume_when_clean()
        if paused and lower_run >= resume_after then
            paused = false
            status.state = 'running'
            note(name .. ' resumed after ' .. resume_after .. ' clean frames')
        end
    end

    -- Counts a frame without an own error, which also clears an old burst.
    local function count_clean()
        if failed then return end
        clean_run = clean_run + 1
        if clean_run == clean_after then status.errors = 0 end
    end

    local function finish(...)
        in_previous = false
        lower_run = lower_run + 1
        if lower_run == clean_after then status.lower_errors = 0 end
        if not stopped and not paused then
            if after_step then
                local ok, problem = pcall(after_step)
                if not ok then failed_step(problem) end
            end
            count_clean()
        end
        return ...
    end

    -- The previous update runs outside pcall: its errors (value and traceback)
    -- reach the game unchanged. One that raised leaves in_previous set, and the
    -- next frame pauses (or stops) this mod and keeps forwarding.
    local function update(...)
        failed = false
        if in_previous then
            in_previous = false
            if not stopped then failed_below() end
        end
        resume_when_clean()
        if step and not stopped and not paused then
            local ok, problem = pcall(step, ...)
            if not ok then failed_step(problem) end
        end
        in_previous = true
        return finish(previous_update(...))
    end

    local function shutdown(...)
        if in_previous then
            in_previous = false
            status.first_failure = status.first_failure or 'the previous update failed'
        end
        local failure = status.first_failure
        if not stopped then
            stopped = true
            if stop_work then
                local ok, why = pcall(stop_work, 'shutdown')
                if not ok then status.stop_error = tostring(why) end
            end
        end
        status.state = failure and ('stopped after: ' .. failure) or 'stopped'
        if previous_shutdown then return previous_shutdown(...) end
    end

    local guard = {status = status}

    function guard.install()
        local env = options.env or _G
        if status.installed then error('guard ' .. name .. ' already installed', 0) end
        previous_update = rawget(env, 'update')
        if type(previous_update) ~= 'function' then error('game update unavailable', 0) end
        previous_shutdown = rawget(env, 'shutdown')
        rawset(env, 'update', update)
        rawset(env, 'shutdown', shutdown)
        status.installed, status.state = true, 'running'
        return guard
    end

    function guard.stop(reason)
        halt(tostring(reason))
    end

    function guard.running()
        return status.installed and not stopped
    end

    return guard
end

return runtime
end
mom_files.native = function(...)
-- game.dll's native functions MOM calls and the native labels and setting
-- descriptor it relies on, verified once per session against Steam build
-- 26088801 before MOM touches the menu (initialize).
local mom = ...
local ffi = require('ffi')
local memory, note, state, get32 = mom.memory, mom.note, mom.state, mom.get32

local GAME_SHA256 = '6D1D4D3BC6FC84801D9F8F1B310E13A603D07409F3D9495D74B42E1D0BB1C08F'
local EXE_SHA256 = '0ACC07DEBE04714AE04281E1A66BD2EB9D3D85232953E32A93C8A3DD0874EABE'
-- The native labels of the escape menu's three tabs (4 bytes each) and of the
-- OPTIONS content's nine categories (one record each, the label at +8).
local TAB_LABELS_RVA = 0x2cc9f30
local CATEGORY_TABLE_RVA, CATEGORY_RECORD = 0x2ca50b0, 48
-- Rows use setting 139 (a BINDINGS activation type): the settings lookup
-- finds it, its value type is none, and no category handler special-cases it,
-- so changing a MODS row never reads or writes a game setting.
local INERT_SETTING, INERT_DESCRIPTOR_RVA = 139, 0x2ca5320
-- {RVA, first bytes, C type}; entry points are verified before first use.
-- Object addresses pass as integers, so a call creates no pointer object.
local NATIVE = {
    set_tab_labels = {0x162bee0, '\x48\x89\x54\x24\x10\x53\x56\x48\x83\xec\x68\x0f\x29\x74\x24\x30',
                      'void (*)(MOM_u64, const MOM_u32 *, int)'},
    select_category = {0x181ac40, '\x40\x53\x48\x83\xec\x20\x48\x8b\xd9\x89\x91\x58\x1e\x14\x00\x39',
                       'void (*)(MOM_u64, int)'},
    set_content_hidden = {0x1819740, '\x48\x89\x5c\x24\x08\x48\x89\x74\x24\x10\x57\x48\x83\xec\x50\x41',
                          'void (*)(MOM_u64, MOM_u8, MOM_u8)'},
    row_reset = {0x16809a0, '\x48\x89\x5c\x24\x10\x48\x89\x74\x24\x18\x48\x89\x7c\x24\x20\x55',
                 'void (*)(MOM_u64, const float *, const float *)'},
    row_release = {0x1680750, '\x48\x89\x5c\x24\x08\x57\x48\x83\xec\x20\x8b\x81\xc0\x7a\x00\x00',
                   'void (*)(MOM_u64)'},
    row_init = {0x167fb70, '\x48\x89\x5c\x24\x08\x57\x48\x83\xec\x70\x48\x8b\xbc\x24\xb0\x00',
                'void (*)(MOM_u64, MOM_vec2, MOM_vec2, MOM_vec2, int, MOM_u64, const void *, MOM_u8)'},
    add_child = {0x12e42d0, '\x40\x53\x48\x83\xec\x20\x4c\x8b\xca\x48\x8b\xd9\x48\x8b\x91\xe0',
                 'void (*)(MOM_u64, MOM_u64)'},
    set_visible = {0x12e4cc0, '\x48\x83\xec\x28\x44\x8b\x01\x4c\x8b\xd1\x41\x8b\xc0\x45\x8b\xc8',
                   'void (*)(MOM_u64, MOM_u8)'},
    set_label = {0x12d3ca0, '\x48\x83\xec\x28\x4c\x8b\xd9\x39\x91\x10\x01\x00\x00\x0f\x84\x80',
                 'void (*)(MOM_u64, MOM_u32)'},
    set_string_arg = {0x12d4660, '\x40\x53\x48\x83\xec\x20\x48\x8b\xd9\x48\x81\xc1\x10\x01\x00\x00',
                      'void (*)(MOM_u64, MOM_u32, const char *)'},
    clear_args = {0x12d1e00, '\x80\xb9\x58\x01\x00\x00\x00\xc6\x81\x58\x01\x00\x00\x00\x0f\x97',
                  'MOM_u8 (*)(MOM_u64)'},
    set_choice = {0x167fa80, '\x80\xb9\xf8\x32\x00\x00\x00\x74\x28\x83\xfa\x10\x73\x23\x48\x63',
                  'void (*)(MOM_u64, MOM_u32)'},
    set_slider = {0x167d560, '\x40\x53\x48\x83\xec\x20\xf3\x0f\x10\x91\xac\x08\x00\x00\x48\x8b',
                  'void (*)(MOM_u64, float)'},
    finish_simple = {0x1688300, '\x48\x89\x5c\x24\x08\x57\x48\x83\xec\x30\x8b\x81\x10\x0b\x00\x00',
                     'void (*)(MOM_u64)'},
    finish_access = {0x1682280, '\x48\x89\x5c\x24\x08\x57\x48\x83\xec\x30\x8b\x81\x50\x57\x00\x00',
                     'void (*)(MOM_u64)'},
    scroll_thumb = {0x16151f0, '\x48\x89\x5c\x24\x10\x57\x48\x83\xec\x40\x48\x8b\xd9\x0f\x29\x74',
                    'void (*)(MOM_u64, float)'},
    scroll_extent = {0x1615890, '\xf3\x0f\x10\xa1\xb0\x07\x00\x00\x0f\x28\xd1\x0f\x2e\xe2\x7a\x02',
                     'void (*)(MOM_u64, float)'},
    set_opacity = {0x12e07e0, '\x40\x57\x48\x83\xec\x20\xf3\x0f\x10\x41\x44\x48\x8b\xf9\x0f\x2e',
                   'void (*)(MOM_u64, float)'},
    scroll_reset = {0x1615800, '\x80\xb9\xb5\x07\x00\x00\x00\x74\x19\xf3\x0f\x10\x89\xbc\x07\x00',
                    'void (*)(MOM_u64)'},
    options_visual = {0x1819810, '\x48\x8b\xc4\x57\x48\x83\xec\x70\x80\xb9\x15\x22\x14\x00\x00\x48',
                      'void (*)(MOM_u64, float)'},
    measure_text = {0x12e5eb0, '\x40\x53\x48\x83\xec\x70\x48\x8b\xd9\x8b\x09\x8b\xc1\xc1\xe8\x12',
                    'void (*)(MOM_u64)'},
    -- Position and size share their first 27 bytes; byte 28 picks the field.
    set_position = {0x12df3b0, '\x48\x89\x5c\x24\x18\x48\x89\x6c\x24\x20\x48\x89\x54\x24\x10\x56' ..
                               '\x57\x41\x57\x48\x83\xec\x20\xf3\x0f\x10\x41\x04', 'void (*)(MOM_u64, MOM_vec2)'},
    set_size = {0x12dee70, '\x48\x89\x5c\x24\x18\x48\x89\x6c\x24\x20\x48\x89\x54\x24\x10\x56' ..
                           '\x57\x41\x57\x48\x83\xec\x20\xf3\x0f\x10\x41\x0c', 'void (*)(MOM_u64, MOM_vec2)'},
    hide_description = {0x167be30, '\x48\x89\x5c\x24\x10\x57\x48\x83\xec\x70\x0f\xb6\xda\x48\x8b\xf9',
                        'void (*)(MOM_u64, MOM_u8, MOM_u8)'},
    -- Posts a UI sound event; the first argument is unused.
    play_sound = {0x11bbaf0, '\x48\x89\x5c\x24\x08\x48\x89\x74\x24\x10\x57\x48\x83\xec\x20\x48',
                  'void (*)(MOM_u64, MOM_u32)'},
}
local NATIVE_LABELS = {
    tabs = {0xd876b36e, 0x78934e12, 0x8c02bd80}, -- GAME, SOCIAL, OPTIONS
    categories = {0x396f27d7, 0x196248d0, 0xa522d2d0, 0x15cecac1, 0x9a688238,
                  0x07e3b100, 0x5db3b764, 0xa7c345ef, 0x9bb47b92},
}

local function initialize()
    if state.initialized then return end
    state.initialized = true
    local ok, err = pcall(function()
        -- The runtime hashes each module file once per session for every mod
        -- (BingusRuntime.hashes): 'game modules unavailable' or 'unsupported
        -- game build' when it refuses.
        local verified, why = memory.verify_build({exe_sha256 = EXE_SHA256, game_sha256 = GAME_SHA256})
        assert(verified, why)
        local base = memory.address(memory.module('game.dll'))
        local native = {}
        local deferred = {}
        for name, entry in pairs(NATIVE) do
            local at = ffi.cast('const uint8_t *', base + entry[1])
            local bytes = memory.read(at, #entry[2])
            if bytes then
                assert(bytes == entry[2], name .. ' changed')
                native[name] = ffi.cast(entry[3], base + entry[1])
            else
                deferred[#deferred + 1] = name
                native[name] = function(...)
                    local now = memory.read(at, #entry[2])
                    assert(now, name .. ' not resident yet')
                    assert(now == entry[2], name .. ' changed')
                    native[name] = ffi.cast(entry[3], base + entry[1])
                    return native[name](...)
                end
            end
        end
        if #deferred > 0 then note('Checked at first use (code not resident yet): ' .. table.concat(deferred, ', ')) end
        for index, label in ipairs(NATIVE_LABELS.tabs) do
            assert(get32(base + TAB_LABELS_RVA + (index - 1) * 4) == label, 'tab labels changed')
        end
        for index, label in ipairs(NATIVE_LABELS.categories) do
            assert(get32(base + CATEGORY_TABLE_RVA + (index - 1) * CATEGORY_RECORD + 8) == label,
                   'category labels changed')
        end
        assert(get32(base + INERT_DESCRIPTOR_RVA) == INERT_SETTING and
               get32(base + INERT_DESCRIPTOR_RVA + 4) == 10 and
               get32(base + INERT_DESCRIPTOR_RVA + 12) == 0, 'setting descriptors changed')
        state.base, state.native = base, native
    end)
    if ok then note('Native options layout verified for current game build.')
    else note('Mod options integration unavailable: ' .. tostring(err)) end
end

-- For the other files and the update.
mom.initialize, mom.NATIVE_LABELS, mom.INERT_SETTING = initialize, NATIVE_LABELS, INERT_SETTING
end
mom_files.options = function(...)
-- Registered options: their texts (which may follow the game's language), their
-- values (applied, saved in ModOptionsMenu.values, and the player's pending
-- edits) and the option model register_option builds from a spec.
local mom = ...
local state, note, loader, translation = mom.state, mom.note, mom.loader, mom.translation
local TEXT_TEMPLATE = mom.TEXT_TEMPLATE -- '#COUNT': src/widgets.lua

-- Limits: characters of a description, names in a choice option.
local DESCRIPTION_LIMIT, MAX_CHOICES = 400, 16
local OFF_TEXT, ON_TEXT = 0xa090be2e, 0x13dc1da2
-- Choice words the game already translates; other text is shown verbatim.
local NATIVE_WORDS = {
    OFF = 0xa090be2e, ON = 0x13dc1da2, NO = 0xef21c0c2, YES = 0x30dbdb29,
    LOW = 0xe1f9ab36, MEDIUM = 0x3134d1fe, HIGH = 0x208f9597, ULTRA = 0x99ffb498,
    DEFAULT = 0x38e6b4e4, CUSTOM = 0x2acf00b1, NORMAL = 0xf3222616, INVERTED = 0x05478062,
    WEAK = 0xe7b8332e, STRONG = 0xd9709682, BASIC = 0xaab9e5da, ADVANCED = 0xe0b81607,
    FULL = 0x3ba052b7, PERFORMANCE = 0x5097df8c, BALANCED = 0xe2135504, QUALITY = 0x61f69557,
    GLOBAL = 0x1d256a7b, ALWAYS = 0xeccb0c50, DISABLED = 0xe480cc2b, HIDDEN = 0xaae829ed,
    VISIBLE = 0xbcab6809, SMALL = 0x818d7022, LARGE = 0xf8c59d6a, SHORT = 0xb008f033,
    DYNAMIC = 0xf54d4908, HOLD = 0x639ee7c1, PRESS = 0x91b91dd3, TAP = 0x26603652,
}
-- Seconds from a change to its save, and from a failed save to the next try.
local VALUES_FILE, SAVE_DELAY, SAVE_RETRY = 'ModOptionsMenu.values', 1, 10
-- The game keeps a slider's min, max, step and value as floats: a magnitude
-- above FLOAT_MAX reaches it as an infinity, a step below FLOAT_MIN (the
-- smallest normal float) as a denormal or 0.
local FLOAT_MAX, FLOAT_MIN, HUGE = 3.4028234663852886e38, 1.1754943508222875e-38, math.huge

-- Text -----------------------------------------------------------------------

local function display_text(text)
    return (text:gsub('[%c]', ' '):gsub('^%s+', ''):gsub('%s+$', ''))
end

-- A registered text: a string, or (API version 2) a function returning one,
-- which is called now and again whenever the escape menu opens, so the text
-- can follow the game's language. Limits count characters, so a Chinese or
-- Cyrillic text gets the same room as an English one. Returns the text to
-- show, or nil when the value is not a usable text.
function translation.resolve(value, limit)
    if type(value) == 'function' then
        local ok, result = pcall(value)
        if not ok then return nil end
        value = result
    end
    if type(value) ~= 'string' or translation.T.length(value) > limit then return nil end
    local text = display_text(value)
    if text == '' or not translation.T.check(text) then return nil end
    return text
end

-- Registered texts given as functions follow the game's language: they are
-- called again whenever the escape menu opens (never per frame). A result
-- that is no longer a usable text keeps the text shown before. Mods keep the
-- category they registered under; only its shown name changes.
function translation.refresh()
    local changed = false
    local function refreshed(value, source, limit, upper)
        if type(source) ~= 'function' then return value end
        local text = translation.resolve(source, limit)
        if not text then return value end
        if upper then text = translation.T.upper(text) end
        changed = changed or text ~= value
        return text
    end
    for _, mod in ipairs(state.mods) do mod.title = refreshed(mod.title, mod.source, 40, true) end
    for _, option in pairs(state.options) do
        local sources = option.sources
        option.label = refreshed(option.label, sources.label, 64)
        if option.description then
            option.description = refreshed(option.description, sources.description, DESCRIPTION_LIMIT)
        end
        for index, source in ipairs(sources.choices) do
            -- The game's own words keep the game's label.
            if option.labels[index] == TEXT_TEMPLATE then
                option.choices[index] = refreshed(option.choices[index], source, 48, true)
            end
        end
    end
    local title, empty = translation.tr('tab.mods'), translation.tr('category.none')
    changed = changed or title ~= state.mods_title or empty ~= state.empty_text
    state.mods_title, state.empty_text = title, empty
    if changed then state.revision = state.revision + 1 end
end

-- The game's Text Language (5 guarded reads), logged when it changes.
function translation.observe()
    local tag, code = translation.T.observe(translation.read, state.base)
    local seen = tag and (tag .. ' (game setting ' .. code .. ')') or (translation.T.language() .. ' (Steam)')
    if seen ~= state.language then
        state.language = seen
        note('Text language: ' .. seen .. '.')
    end
end

-- Values ---------------------------------------------------------------------

local function values_path()
    local directory = type(loader) == 'table' and loader.log_directory
    if type(directory) ~= 'string' or directory == '' then
        local local_app_data = os.getenv('LOCALAPPDATA')
        if not local_app_data then return nil end
        directory = local_app_data .. '/CowboyBingus/Helldivers2/Logs'
    end
    return directory .. '/' .. VALUES_FILE
end

-- The values file's text for id -> encoded value: a line of id, tab, value
-- each, sorted.
local function values_text(values)
    local lines = {}
    for id, text in pairs(values) do lines[#lines + 1] = id .. '\t' .. text end
    table.sort(lines)
    return table.concat(lines, '\n') .. '\n'
end

-- The text of a file, or nil when it cannot be read.
local function read_text(path)
    local file = io.open(path, 'rb')
    if not file then return nil end
    local text = file:read('*a')
    file:close()
    return text
end

-- id -> text for each line of a values file; nil when it holds none.
local function parse_values(text)
    local values, found = {}, false
    for id, value in text:gmatch('([^\t\r\n]+)\t([^\r\n]*)') do values[id], found = value, true end
    return found and values or nil
end

-- The saved values: the values file's, or its backup's when the file is
-- missing, unreadable or holds no value (as a save interrupted before v1.2
-- could leave it). state.written: the file's text as last read or written,
-- when MOM would write the same text for the same values (save_values skips
-- that text); never a backup's, so the next save writes the file.
local function saved_values()
    if state.saved then return state.saved end
    state.saved = {}
    local path = values_path()
    local text = path and read_text(path)
    local values = text and parse_values(text)
    if values then
        if values_text(values) == text then state.written = text end
    else
        values = path and parse_values(read_text(path .. '.bak') or '')
        if values then note('Option values read from the backup ' .. VALUES_FILE .. '.bak.') end
    end
    state.saved = values or state.saved
    return state.saved
end

local function encode(option, value)
    if option.kind == 'toggle' then return value and 'true' or 'false' end
    if option.kind == 'choice' then return tostring(value) end
    return string.format('%.6g', value)
end

local function valid_value(option, value)
    if option.kind == 'toggle' then return type(value) == 'boolean' end
    if type(value) ~= 'number' or value ~= value then return false end
    if option.kind == 'choice' then
        return value % 1 == 0 and value >= 1 and value <= #option.choices
    end
    return value >= option.min and value <= option.max
end

-- Slider values snap to the option's step; decimals avoid float noise. NaN
-- and the infinities snap to nil, which every caller refuses: a registered
-- default, set(), the values file and a row's value (src/rows.lua). Without
-- this, NaN came out as NaN or as min depending on whether the game's LuaJIT
-- had compiled the call (its compiled math.max drops a NaN).
local function snap(option, value)
    if not (value > -HUGE and value < HUGE) then return nil end
    local steps = math.floor((value - option.min) / option.step + 0.5)
    local snapped = math.min(option.max, math.max(option.min, option.min + steps * option.step))
    return tonumber(string.format('%.' .. option.decimals .. 'f', snapped))
end

local function decode(option, text)
    if option.kind == 'toggle' then
        if text == 'true' then return true elseif text == 'false' then return false end
        return nil
    end
    local value = tonumber(text)
    if value == nil then return nil end
    if option.kind == 'slider' then value = snap(option, value) end
    return valid_value(option, value) and value or nil
end

-- Writes the values file through <file>.tmp, checking every write and the
-- close, then moves the old file to <file>.bak and the temp file into its
-- place. A save interrupted at any point leaves the old file or, between the
-- two renames, its backup, which loading falls back to. Returns true, or false
-- and the reason; a failure leaves the old file in place.
local function write_values(path, text)
    local temp, backup = path .. '.tmp', path .. '.bak'
    local file, reason = io.open(temp, 'wb')
    if not file then return false, reason end
    local written, write_error = file:write(text)
    local closed, close_error = file:close()
    if not (written and closed) then
        os.remove(temp)
        return false, write_error or close_error
    end
    os.remove(backup)
    local moved = os.rename(path, backup)
    local replaced, rename_error = os.rename(temp, path)
    if replaced then return true end
    if moved then os.rename(backup, path) end
    os.remove(temp)
    return false, rename_error
end

-- Saves every value: saved ones of options not registered this session too.
-- A text the file already holds is not written again. A failed save keeps
-- the values due and tries again SAVE_RETRY seconds later; the first failure
-- after a save that worked is logged.
local function save_values()
    local path = values_path()
    local merged = {}
    for id, text in pairs(saved_values()) do merged[id] = text end
    for id, option in pairs(state.options) do merged[id] = encode(option, state.values[id]) end
    local text = values_text(merged)
    if text == state.written then state.dirty = false; return end
    local saved, reason = false, 'no folder for ' .. VALUES_FILE
    if path then saved, reason = write_values(path, text) end
    if saved then
        state.written, state.dirty, state.save_failed = text, false, false
        return
    end
    state.dirty, state.save_timer = true, SAVE_RETRY
    if not state.save_failed then note('Cannot save option values: ' .. tostring(reason)) end
    state.save_failed = true
end

local function changed(option, value)
    if state.values[option.id] == value then return end
    state.values[option.id] = value
    state.saved[option.id] = encode(option, value)
    state.dirty, state.save_timer = true, SAVE_DELAY
    for _, callback in ipairs(state.callbacks[option.id] or {}) do
        local ok, err = pcall(callback, value, option.id)
        if not ok then note('Option callback for ' .. option.id .. ' failed: ' .. tostring(err)) end
    end
end

-- Player edits wait for the apply action; editing back to the applied value
-- withdraws the edit.
local function set_pending(id, value)
    local had = state.pending[id] ~= nil
    if value == state.values[id] then value = nil end
    state.pending[id] = value
    if had ~= (value ~= nil) then state.pending_count = state.pending_count + (had and -1 or 1) end
end

-- What a row shows: the pending edit, else the applied value.
local function shown_value(option)
    local value = state.pending[option.id]
    if value == nil then value = state.values[option.id] end
    return value
end

-- Applies every pending edit in registration order, then saves at once, as
-- the game saves its settings on apply.
local function apply_pending()
    local options = {}
    for id in pairs(state.pending) do options[#options + 1] = state.options[id] end
    table.sort(options, function(a, b) return a.sequence < b.sequence end)
    local pending = state.pending
    state.pending, state.pending_count = {}, 0
    for _, option in ipairs(options) do changed(option, pending[option.id]) end
    save_values()
    return #options
end

local function drop_pending()
    state.pending, state.pending_count = {}, 0
end

-- Option model ---------------------------------------------------------------

-- The fields of one option type, from its spec. Each returns the option, or nil
-- and the reason when the spec does not describe a valid option of that type.
local function toggle_fields(option, spec)
    option.labels, option.default = {OFF_TEXT, ON_TEXT}, spec.default == true
    if spec.default ~= nil and type(spec.default) ~= 'boolean' then return nil, 'invalid default' end
    return option
end

local function choice_fields(option, spec)
    local choices = spec.choices
    if type(choices) ~= 'table' or #choices < 2 or #choices > MAX_CHOICES then
        return nil, 'choices must list 2 to ' .. MAX_CHOICES .. ' names'
    end
    option.choices, option.labels = {}, {}
    for index, choice in ipairs(choices) do
        local text = translation.resolve(choice, 48)
        if not text then return nil, 'invalid choice name' end
        option.choices[index] = translation.T.upper(text)
        -- A word the game translates itself (ON, OFF, LOW...) shows the game's own label.
        option.labels[index] = NATIVE_WORDS[option.choices[index]] or TEXT_TEMPLATE
        option.sources.choices[index] = choice
    end
    option.default = spec.default == nil and 1 or spec.default
    return option
end

-- Decimal places a slider shows: as many as its step needs, at most 3, and at
-- least 1 when min is not a whole number.
local function slider_decimals(min, step)
    local decimals = 0
    while decimals < 3 and math.abs(step * 10 ^ decimals - math.floor(step * 10 ^ decimals + 0.5)) > 1e-6 do
        decimals = decimals + 1
    end
    if min % 1 ~= 0 then decimals = math.max(decimals, 1) end
    return decimals
end

local function slider_fields(option, spec)
    local min, max, step = spec.min, spec.max, spec.step or 1
    if type(min) ~= 'number' or type(max) ~= 'number' or type(step) ~= 'number'
       or not (min < max) or step <= 0 or step > max - min then
        return nil, 'slider needs min < max and 0 < step <= max - min'
    end
    -- An infinity, a range or step a float cannot hold, or a NaN step (NaN
    -- fails every comparison above).
    if not (min >= -FLOAT_MAX and max <= FLOAT_MAX and max - min <= FLOAT_MAX and step >= FLOAT_MIN) then
        return nil, 'slider min, max and step must be finite floats'
    end
    option.min, option.max, option.step, option.decimals = min, max, step, slider_decimals(min, step)
    option.default = spec.default == nil and min or spec.default
    if type(option.default) == 'number' then option.default = snap(option, option.default) end
    return option
end

-- sources: the registered values (strings or functions), for translation.refresh.
local function new_option(id, spec)
    local kind = spec.type
    local option = {id = id, kind = kind, label = translation.resolve(spec.label, 64), gap = spec.gap == true,
                    sources = {label = spec.label, description = spec.description, choices = {}}}
    if spec.description ~= nil then
        option.description = translation.resolve(spec.description, DESCRIPTION_LIMIT)
        if not option.description then return nil, 'invalid description' end
    end
    local fields
    if kind == 'toggle' then
        fields = toggle_fields
    elseif kind == 'choice' then
        fields = choice_fields
    elseif kind == 'slider' then
        fields = slider_fields
    else
        return nil, 'type must be toggle, choice or slider'
    end
    local built, reason = fields(option, spec)
    if not built then return nil, reason end
    if not valid_value(option, option.default) then return nil, 'invalid default' end
    return option
end

-- Texts given as functions may differ between registrations (another
-- language): only texts given as strings are compared.
local function same_option(a, b)
    local function same_text(x, y, source_x, source_y)
        return type(source_x) == 'function' or type(source_y) == 'function' or x == y
    end
    local sa, sb = a.sources, b.sources
    if a.kind ~= b.kind or a.default ~= b.default or not same_text(a.label, b.label, sa.label, sb.label)
       or not same_text(a.description, b.description, sa.description, sb.description) then
        return false
    end
    if a.kind == 'choice' then
        if #a.choices ~= #b.choices then return false end
        for index = 1, #a.choices do
            if not same_text(a.choices[index], b.choices[index], sa.choices[index], sb.choices[index]) then
                return false
            end
        end
        return true
    end
    if a.kind == 'slider' then return a.min == b.min and a.max == b.max and a.step == b.step end
    return true
end

-- For the other files.
mom.display_text, mom.saved_values, mom.encode, mom.decode = display_text, saved_values, encode, decode
mom.valid_value, mom.snap, mom.save_values, mom.SAVE_DELAY = valid_value, snap, save_values, SAVE_DELAY
mom.set_pending, mom.shown_value = set_pending, shown_value
mom.apply_pending, mom.drop_pending = apply_pending, drop_pending
mom.new_option, mom.same_option, mom.MAX_CHOICES = new_option, same_option, MAX_CHOICES
end
mom_files.rows = function(...)
-- Option rows and category pages: a mod's options built into the game's own
-- rows on the shown category's panel, then checked and polled every frame.
local mom = ...
local ffi = require('ffi')
local state = mom.state
local get32, getf, get64, put8, put32, putf = mom.get32, mom.getf, mom.get64, mom.put8, mom.put32, mom.putf
local valid_pointer, PIVOT, vector, aligned = mom.valid_pointer, mom.PIVOT, mom.vector, mom.aligned
local INERT_SETTING = mom.INERT_SETTING -- setting 139: src/native.lua
local show_text, shows_text, TEXT_TEMPLATE = mom.show_text, mom.shows_text, mom.TEXT_TEMPLATE
local snap, set_pending, shown_value = mom.snap, mom.set_pending, mom.shown_value

local ROW_ARRAY, MAX_ROWS = 144000, 32
-- Category panels, in category order. Each family keeps its row count, layout
-- and settings pointer at its own offsets; all panels share the row array.
local PANELS = {
    [0] = {offset = 1150848, family = 'simple', selected = 2872}, -- GAMEPLAY
    [1] = {offset = 1179528, family = 'large', selected = 33296}, -- DISPLAY
    [2] = {offset = 1253248, family = 'large', selected = 33296}, -- GRAPHICS
    [3] = {offset = 1287376, family = 'simple', selected = 2872}, -- AUDIO
    [4] = {offset = 1153728, family = 'simple', selected = 2872}, -- HUD
    [5] = {offset = 1156616, family = 'access', selected = 22392}, -- ACCESSIBILITY
    [6] = {offset = 1290256, family = 'simple', selected = 2880}, -- CONTROLLER
    [7] = {offset = 1293152, family = 'simple', selected = 2872}, -- MOUSE & KEYBOARD
}
local FAMILIES = {
    simple = {count = 2832, x = 2836, gap = 2840, height = 2844, settings = 2856, scrolls = 2830},
    large = {count = 33256, x = 33260, gap = 33264, height = 33268, settings = 33280, scrolls = 33254},
    access = {count = 22352, x = 22356, gap = 22360, settings = 22376, scrolls = 22350},
}
local PANEL_ROWS, PANEL_CONTAINER, PANEL_SCROLL, SCROLL_POSITION = 2816, 544, 816, 1976
local VIEW_HEIGHT, ROW_HEIGHT, GAP_HEIGHT = 806, 64, 32
-- Option rows (31464 bytes each).
local ROW_STRIDE, ROW_TEXT, ROW_SELECTOR, ROW_VALUE_TEXT = 31464, 3992, 16016, 16832
local ROW_INDEX, ROW_SLIDER, ROW_SLIDER_VALUE, ROW_SETTING = 29068, 29176, 31408, 31428
local ROW_CHOICE_COUNT, ROW_CHOICES = 29072, 29080 -- selector choice count and label IDs
local DESCRIPTOR_SIZE = 216
local WIDGET_INT_SLIDER, WIDGET_FLOAT_SLIDER, WIDGET_SELECTOR = 0, 1, 2

-- Native rows ----------------------------------------------------------------

-- The same layout as the game's descriptors (a float slider of 0.01 steps
-- there uses +48 = 6, +52 = 1, format 0x6220), 16-byte aligned like theirs.
-- Returns the descriptor and the block that keeps it alive.
local function descriptor(option)
    local blob, block = aligned(DESCRIPTOR_SIZE)
    local words, floats = ffi.cast('MOM_u32 *', blob), ffi.cast('float *', blob)
    words[0], words[1], words[3], words[4] = INERT_SETTING, 10, 0, TEXT_TEMPLATE
    if option.kind == 'slider' then
        words[2] = option.decimals == 0 and WIDGET_INT_SLIDER or WIDGET_FLOAT_SLIDER
        floats[9], floats[10], floats[11] = option.min, option.max, option.step
        floats[12], floats[13] = option.decimals == 0 and 20 or 6, 1
        -- Float values: two integer digits and the option's decimal places.
        words[14] = option.decimals == 0 and 0 or 0x6200 + option.decimals * 16
    else
        words[2], words[16] = WIDGET_SELECTOR, #option.labels
        for index, label in ipairs(option.labels) do words[16 + index] = label end
    end
    return blob, block
end

local function row_value(entry)
    if entry.option.kind == 'slider' then return getf(entry.row + ROW_SLIDER_VALUE) end
    return get32(entry.row + ROW_INDEX)
end

-- The value a row holds, or nil when the option cannot take it: a slider at
-- NaN or an infinity (snap), or a selector index past the option's choices.
-- The player's input never makes one; the game or another mod could.
local function decode_row(option, raw)
    if option.kind == 'toggle' then return raw == 1 end
    if option.kind == 'choice' then return raw < #option.choices and raw + 1 or nil end
    return snap(option, raw)
end

-- Custom choice words share the '#COUNT' template, so the shown word is the
-- value widget's argument.
local function show_choice(entry)
    local option = entry.option
    if option.kind ~= 'choice' then return end
    local index = get32(entry.row + ROW_INDEX)
    local text = option.choices[index + 1]
    if text and option.labels[index + 1] == TEXT_TEMPLATE then
        show_text(entry.row + ROW_VALUE_TEXT, text)
    end
end

local function apply_value(entry, value)
    local option, native = entry.option, state.native
    if option.kind == 'slider' then
        native.set_slider(entry.row + ROW_SLIDER, value)
    else
        local index = option.kind == 'toggle' and (value and 1 or 0) or value - 1
        native.set_choice(entry.row + ROW_SELECTOR, index)
        show_choice(entry)
    end
    entry.raw = row_value(entry)
end

local function finish_panel(panel, family, name)
    local native = state.native
    local count = get32(panel + family.count)
    local height = count * ROW_HEIGHT - getf(panel + family.gap)
    if family.height then putf(panel + family.height, height) end
    if name == 'simple' then native.finish_simple(panel); return end
    if name == 'access' then native.finish_access(panel); return end
    -- The large panels finish inline in their builders; this is the same sequence.
    local scroll = panel + PANEL_SCROLL
    if count == 0 then
        native.set_opacity(scroll, 0)
        put8(panel + family.scrolls, 0)
        return
    end
    native.scroll_thumb(scroll, math.min(1, VIEW_HEIGHT / height))
    native.scroll_extent(scroll, height - VIEW_HEIGHT)
    if height > VIEW_HEIGHT then
        native.set_opacity(scroll, 1)
        put8(panel + family.scrolls, 1)
    else
        native.set_opacity(scroll, 0)
        if getf(scroll + SCROLL_POSITION) ~= 0 then
            putf(scroll + SCROLL_POSITION, 0)
            native.scroll_reset(scroll)
        end
        put8(panel + family.scrolls, 0)
    end
end

-- Category pages -------------------------------------------------------------

-- Every panel build first releases all rows, last to first, which detaches
-- them from whichever panel listed them. The reset loads both rectangles with
-- movaps, so they must be 16-byte aligned.
local ZERO_RECT
ZERO_RECT, state.zero_rect_block = aligned(16) -- the block stays referenced, so it is never collected
ZERO_RECT = ffi.cast('const float *', ZERO_RECT)
local function release_rows(rows)
    for index = MAX_ROWS - 1, 0, -1 do
        local row = rows + ROW_STRIDE * index
        state.native.row_reset(row, ZERO_RECT, ZERO_RECT)
        state.native.row_release(row)
    end
end

-- What a row shows: the page control (src/view.lua) its page, an option its
-- pending edit or applied value.
local function row_shown(option) return option.value or shown_value(option) end

-- Replaces the rows the game built for category `index` with the options of
-- the mod on that button (or the page control's row), following the panel
-- builders: released rows, native row initialisation from a descriptor, the
-- same positions and gaps, then the panel's own finishing layout.
local function build_page(view, index)
    local native = state.native
    local spec = PANELS[index]
    local family = FAMILIES[spec.family]
    local panel = view.content + spec.offset
    local rows = get64(panel + PANEL_ROWS)
    if rows ~= view.content + ROW_ARRAY then return false end
    local settings = get64(panel + family.settings)
    if not valid_pointer(settings) then settings = 0 end
    local mod = view.buttons[index + 1]
    local options = mod and mod.order or {}
    local count = math.min(#options, MAX_ROWS)
    local page = {index = index, entries = {}}
    release_rows(rows)
    local gap = 0
    for position = 1, count do
        local option = options[position]
        if option.gap and position > 1 then gap = gap - GAP_HEIGHT end
        local row = rows + ROW_STRIDE * (position - 1)
        native.row_init(row, vector(0, (position - 1) * -ROW_HEIGHT + gap), PIVOT, PIVOT, 10,
                        settings, option.descriptor, 1)
        native.add_child(panel + PANEL_CONTAINER, row)
        show_text(row + ROW_TEXT, option.label)
        local entry = {row = row, option = option}
        apply_value(entry, row_shown(option))
        page.entries[position] = entry
    end
    put32(panel + family.count, count)
    putf(panel + family.x, 0)
    putf(panel + family.gap, gap)
    if get32(panel + spec.selected) >= count then put32(panel + spec.selected, 0) end
    finish_panel(panel, family, spec.family)
    view.page = page
    return true
end

-- The page is intact while the panel lists exactly its rows and each still
-- shows its option; a revert or device change rebuilds the panel natively,
-- and the DISPLAY panel's settings reload rewrites rows 8 and 11 in place
-- (their choice lists), so selectors check their choices too.
local function page_intact(view)
    local page = view.page
    local family = FAMILIES[PANELS[page.index].family]
    local panel = view.content + PANELS[page.index].offset
    if get32(panel + family.count) ~= #page.entries then return false end
    for _, entry in ipairs(page.entries) do
        local row, option = entry.row, entry.option
        if get32(row + ROW_SETTING) ~= INERT_SETTING or not shows_text(row + ROW_TEXT, option.label) then
            return false
        end
        if option.kind ~= 'slider' and (get32(row + ROW_CHOICE_COUNT) ~= #option.labels
                                        or get32(row + ROW_CHOICES) ~= option.labels[1]) then
            return false
        end
    end
    return true
end

-- A row the player changed: the page control's row turns the page
-- (option.turn), an option's row becomes a pending edit.
local function take_row(view, entry, raw, value)
    entry.raw = raw
    show_choice(entry)
    local option = entry.option
    if option.turn then option.turn(view, value) else set_pending(option.id, value) end
end

-- A row value the option cannot take (decode_row) is refused: the row is set
-- back to the value it showed, once. A row that stays at NaN after that
-- compares unequal to itself on every frame, so it is left alone instead of
-- written again each frame.
local function poll_page(view)
    for _, entry in ipairs(view.page.entries) do
        local raw = row_value(entry)
        if raw ~= entry.raw then
            local value = decode_row(entry.option, raw)
            if value ~= nil then
                take_row(view, entry, raw, value)
            elseif raw == raw or entry.raw == entry.raw then
                apply_value(entry, row_shown(entry.option))
            end
        end
    end
end

-- The page entry on the row the panel has selected (hovered with the mouse),
-- the same row the game's own description follows.
local function selected_entry(view)
    local page = view.page
    if not page then return nil end
    local spec = PANELS[page.index]
    return page.entries[get32(view.content + spec.offset + spec.selected) + 1]
end

-- For the other files.
mom.descriptor, mom.apply_value, mom.build_page = descriptor, apply_value, build_page
mom.page_intact, mom.poll_page, mom.selected_entry = page_intact, poll_page, selected_entry
mom.MAX_ROWS = MAX_ROWS
end
mom_files.view = function(...)
-- The MODS view: the idle gate (is the escape menu open on top?), entering,
-- keeping and leaving the MODS tab, the description following the selection,
-- and applying or discarding edits as the OPTIONS tab does.
local mom = ...
local ffi, bit = require('ffi'), require('bit')
local state, note, translation = mom.state, mom.note, mom.translation
local fill, valid_pointer, read_pointer = mom.fill, mom.valid_pointer, mom.read_pointer
local get8, get32, get64, put8, put32 = mom.get8, mom.get32, mom.get64, mom.put8, mom.put32
local apply_pending, drop_pending, save_values = mom.apply_pending, mom.drop_pending, mom.save_values
local label_categories, restore_categories = mom.label_categories, mom.restore_categories
local describe, release_description = mom.describe, mom.release_description
local build_page, page_intact, poll_page = mom.build_page, mom.page_intact, mom.poll_page
local selected_entry, apply_value, descriptor = mom.selected_entry, mom.apply_value, mom.descriptor
local CATEGORIES, MOD_BUTTONS, OPTIONS_TAB = mom.CATEGORIES, mom.MOD_BUTTONS, mom.OPTIONS_TAB
local TEXT_TEMPLATE, MAX_CHOICES = mom.TEXT_TEMPLATE, mom.MAX_CHOICES

local MENU_SYSTEM_PTR_RVA, UI_STATE_PTR_RVA = 0x2e38170, 0x2e38160
local UI_STACK, UI_STACK_ENTRIES = 0x429c, 5 -- five screen types, then their count
local ESCAPE_MENU_SCREEN, ESCAPE_MENU_TYPE = 200, 1
-- Escape menu: one tab bar over the GAME, SOCIAL and OPTIONS contents; the
-- screen's shown content is a tab index.
local SHOWN_CONTENT = 8
-- OPTIONS content: a column of nine category buttons and one panel per category.
local OPTIONS_CONTENT = 3010456
local CURRENT_CATEGORY, PREVIOUS_CATEGORY = 1318488, 1318492
-- Apply, as on the OPTIONS tab: player edits stay pending until the game's
-- apply action. The unapplied-changes flag makes the game show APPLY (hint 2)
-- and meet tab switches and back with its UNAPPLIED CHANGES dialog (mode 0),
-- whose confirm discards the edits. Native settings never change on MODS, so
-- the game's own apply (which also needs its pending settings to differ) and
-- RESET TO DEFAULT never run there.
local UNAPPLIED = 1319449
local DIALOG, DIALOG_MODE, DIALOG_STATE, DIALOG_CONFIRM, DIALOG_CONFIRM_ACTION = 1296040, 19748, 19752, 4608, 12072
local DIALOG_CANCEL, DIALOG_CANCEL_ACTION = 12160, 19624
local DIALOG_OPEN, UNAPPLIED_MODE, VISIBLE_FLAG = 2, 0, 0x10
-- The game's own confirm of mode 0 reloads the shown panel from the live
-- settings, and the DISPLAY panel's reload then rewrites rows 8 and 11 as its
-- resolution lists. Once open (texts and buttons set), the dialog is switched
-- to a mode the game's confirm ignores, and MOM discards instead.
local NEUTRAL_MODE = 2
-- Input actions evaluated this frame: byte 0 of owner + 808 + 32 * (97 *
-- group + action). Apply is Menu.ExtraOption1 (Tab), group 0.
local INPUT_OWNER_PTR_RVA, ACTION_STATES, ACTION_STRIDE, GROUP_ACTIONS, ACTION_GROUPS = 0x2e38250, 808, 32, 97, 13
local MENU_GROUP, APPLY_ACTION, APPLY_SOUND = 0, 12, 1183616600
-- Pages: with more mods than MOD_BUTTONS, the buttons show PAGE_MODS mods at a
-- time and the last button the page control. Its row is a selector whose
-- choices are the pages, so there are at most MAX_CHOICES (16, the game's
-- selector limit) pages and MAX_MODS mods.
local PAGE_MODS = MOD_BUTTONS - 1
local MAX_MODS = PAGE_MODS * MAX_CHOICES

-- Mods and the MODS view -----------------------------------------------------

-- Mods in button order: alphabetical, mods with the same shown name in the
-- order they registered. Registration admits MAX_MODS (api.register_option).
local function before(a, b)
    if a.title ~= b.title then return a.title < b.title end
    return a.sequence < b.sequence
end
local function mod_list()
    local list = {}
    for index, mod in ipairs(state.mods) do list[index] = mod end
    table.sort(list, before)
    return list
end

-- What each category button shows: with up to MOD_BUTTONS mods, view.mods
-- itself. With more, page state.mods_page of PAGE_MODS mods (false where a
-- last page runs out) and the page control on the last button.
local function button_list(view)
    local mods = view.mods
    if #mods <= MOD_BUTTONS then return mods end
    local buttons, first = {}, state.mods_page * PAGE_MODS
    for index = 1, PAGE_MODS do buttons[index] = mods[first + index] or false end
    buttons[MOD_BUTTONS] = view.control
    return buttons
end

-- Whether category button `index` shows a mod or the page control. Button 0
-- shows the empty text when no mod has registered.
local function shows(view, index)
    return index == 0 or view.buttons[index + 1]
end

-- The player turned the page control's row to page `value`: only the category
-- buttons change. The shown category stays the page control's.
local function turn_page(view, value)
    local control = view.control
    state.mods_page = value - 1
    control.order[1].value = value
    control.title = translation.tr('category.page', {page = value, pages = control.pages})
    view.buttons = button_list(view)
    label_categories(view)
    note('Showing mods page ' .. value .. ' of ' .. control.pages .. '.')
end

-- The page control: a category of one choice row naming the pages. The row
-- has no option id, so it is never an edit; turning it calls turn_page.
local function page_control(count)
    local pages = math.ceil(count / PAGE_MODS)
    state.mods_page = math.min(state.mods_page, pages - 1)
    local tr, page = translation.tr, state.mods_page + 1
    local option = {kind = 'choice', label = tr('page.label'), description = tr('page.description'), choices = {},
                    labels = {}, gap = false, value = page, turn = turn_page}
    for index = 1, pages do
        option.choices[index] = tr('page.value', {page = index, pages = pages})
        option.labels[index] = TEXT_TEMPLATE
    end
    option.descriptor, option.descriptor_block = descriptor(option)
    return {title = tr('category.page', {page = page, pages = pages}), order = {option}, pages = pages}
end

-- view.mods, view.control (the page control, when needed) and view.buttons
-- for the mods registered now.
local function list_mods(view)
    view.mods = mod_list()
    view.control = #view.mods > MOD_BUTTONS and page_control(#view.mods) or nil
    view.buttons = button_list(view)
end

-- The idle gate, run every frame: one read of the UI stack (its entries and
-- their count) answers whether the escape menu is open; only then is its
-- screen pointer read.
local ui_stack = ffi.new('MOM_u32[?]', UI_STACK_ENTRIES + 1)
local function escape_menu()
    local base = state.base
    local ui = get64(base + UI_STATE_PTR_RVA)
    if not valid_pointer(ui) or not fill(ui_stack, ui + UI_STACK, 4 * (UI_STACK_ENTRIES + 1)) then
        return nil, 'closed'
    end
    local depth = ui_stack[UI_STACK_ENTRIES]
    if depth > UI_STACK_ENTRIES then return nil, 'closed' end
    local open = false
    for index = 0, depth - 1 do
        if ui_stack[index] == ESCAPE_MENU_TYPE then open = true end
    end
    if not open then return nil, 'closed' end
    if ui_stack[depth - 1] ~= ESCAPE_MENU_TYPE then return nil, 'covered' end
    local menu = get64(base + MENU_SYSTEM_PTR_RVA)
    local screen = valid_pointer(menu) and read_pointer(menu + ESCAPE_MENU_SCREEN)
    if not screen or screen % 8 ~= 0 then return nil, 'closed' end
    return screen, 'open'
end

-- Switches the shown panel through the game's own category selection, which
-- deactivates the previous panel and builds the next one. The selection keeps
-- no previous index itself, so it is written first; reselecting the shown
-- category goes through another panel to force a fresh build.
local function select_category(content, shown, target)
    local native = state.native
    if shown == target then
        local other = target == 0 and 3 or 0
        put32(content + PREVIOUS_CATEGORY, shown)
        native.select_category(content, other)
        shown = other
    end
    put32(content + PREVIOUS_CATEGORY, shown)
    native.select_category(content, target)
end

-- The screen runs the OPTIONS content's visual pass (layout, category button
-- states, row animation, description box) only while OPTIONS is the current
-- tab, so the MODS tab runs it once per frame itself: without it a menu opened
-- on another tab is never laid out. The description then follows the selection.
local function update_visuals(view, dt)
    state.native.options_visual(view.content, dt)
    local entry = selected_entry(view)
    if entry ~= view.described then describe(view, entry) end
end

-- Whether an input action triggered this frame, on any device or binding.
-- The input owner is live whenever the menu is: the visual pass reads it.
local function action_triggered(group, action)
    local owner = get64(state.base + INPUT_OWNER_PTR_RVA)
    if not valid_pointer(owner) or group >= ACTION_GROUPS or action >= GROUP_ACTIONS then return false end
    return get8(owner + ACTION_STATES + ACTION_STRIDE * (GROUP_ACTIONS * group + action)) ~= 0
end

-- Whether a dialog button's action (u32 group, u32 action at key) triggered.
local function key_triggered(dialog, key)
    return action_triggered(get32(dialog + key), get32(dialog + key + 4))
end

local function button_triggered(dialog, button, key)
    return bit.band(get32(dialog + button), VISIBLE_FLAG) ~= 0 and key_triggered(dialog, key)
end

-- The UNAPPLIED CHANGES dialog, decided as the game decides it (0x199ce60):
-- confirmed when its shown confirm button's action triggers, cancelled when
-- its cancel button's does. When the game's input update runs before this one
-- it has already closed the dialog and cleared the confirm action (Menu.Select)
-- but not the cancel action (Menu.Back), so a dialog seen open and closed
-- since was confirmed unless its cancel action triggered. view.dialog: 'open'
-- once seen open, 'decided' once decided while still open (its closing then
-- decides nothing again). Nil when no dialog is involved.
local function unapplied_dialog(view)
    local dialog = view.content + DIALOG
    local mode = get32(dialog + DIALOG_MODE)
    local open = get32(dialog + DIALOG_STATE) == DIALOG_OPEN and (mode == UNAPPLIED_MODE or mode == NEUTRAL_MODE)
    local seen = view.dialog
    if not open then
        view.dialog = nil
        if seen ~= 'open' then return nil end
        return key_triggered(dialog, DIALOG_CANCEL_ACTION) and 'cancelled' or 'confirmed'
    end
    if seen == 'decided' then return 'open' end
    view.dialog = 'decided'
    if button_triggered(dialog, DIALOG_CONFIRM, DIALOG_CONFIRM_ACTION) then return 'confirmed' end
    if button_triggered(dialog, DIALOG_CANCEL, DIALOG_CANCEL_ACTION) then return 'cancelled' end
    view.dialog = 'open'
    return 'open'
end

-- Drops the pending edits and shows the applied values on the page's rows; the
-- page control's row (no option id) keeps its page.
local NO_ENTRIES = {}
local function discard_pending(view)
    drop_pending()
    for _, entry in ipairs(view.page and view.page.entries or NO_ENTRIES) do
        local id = entry.option.id
        if id then apply_value(entry, state.values[id]) end
    end
    note('Discarded unapplied option changes.')
end

-- Applies the pending edits on the apply action, discards them when the
-- UNAPPLIED CHANGES dialog is confirmed, and keeps the game's unapplied flag
-- in step with them. Nothing runs while no edit is pending.
local function update_apply(view)
    if state.pending_count > 0 then
        local dialog = unapplied_dialog(view)
        if dialog == 'confirmed' then
            discard_pending(view)
        elseif not dialog and action_triggered(MENU_GROUP, APPLY_ACTION) then
            note('Applied ' .. apply_pending() .. ' option changes.')
            state.native.play_sound(0, APPLY_SOUND)
        end
    else
        view.dialog = nil
    end
    local unapplied = state.pending_count > 0 and 1 or 0
    if unapplied ~= view.unapplied then
        put8(view.content + UNAPPLIED, unapplied)
        view.unapplied = unapplied
    end
end

-- Neutralises the UNAPPLIED CHANGES dialog once it is open. It finishes
-- opening inside the visual pass, which runs after update_apply, so this runs
-- after that pass: no frame leaves the game's own confirm armed. A dialog that
-- opened in that pass is watched from here, so a confirm on the game's next
-- input update counts even though update_apply never saw the dialog open.
local function neutralize_dialog(view)
    if state.pending_count == 0 then return end
    local dialog = view.content + DIALOG
    if get32(dialog + DIALOG_STATE) ~= DIALOG_OPEN then return end
    local mode = get32(dialog + DIALOG_MODE)
    if mode == UNAPPLIED_MODE then
        put32(dialog + DIALOG_MODE, NEUTRAL_MODE)
        mode = NEUTRAL_MODE
    end
    if mode == NEUTRAL_MODE and not view.dialog then view.dialog = 'open' end
end

-- Values set from code (api.set) since the last step, by option id.
local function clear_queued()
    for id in pairs(state.queued) do state.queued[id] = nil end
    state.queued_any = false
end

-- Shows the values set from code on the page's rows. Runs in the step, once the
-- view and its page have been checked this frame.
local function apply_queued(view)
    local queued = state.queued
    for _, entry in ipairs(view.page.entries) do
        local id = entry.option.id
        if queued[id] then apply_value(entry, state.values[id]) end
    end
    clear_queued()
end

local function enter_view(screen)
    local native = state.native
    local content = screen + OPTIONS_CONTENT
    local shown = get32(content + CURRENT_CATEGORY)
    -- described: the entry the description box shows; false until first set.
    -- unapplied: the game's unapplied-changes flag as last written.
    -- dialog: the UNAPPLIED CHANGES dialog as watched (unapplied_dialog).
    local view = {screen = screen, content = content, revision = state.revision,
                  saved = shown < MOD_BUTTONS and shown or 0, described = false,
                  unapplied = 0, dialog = nil}
    list_mods(view)
    -- The game's tab switch hid every content; MODS shows the OPTIONS content,
    -- which the screen feeds input while its shown content is OPTIONS (its
    -- visual pass follows the tab instead: update_visuals).
    put32(screen + SHOWN_CONTENT, OPTIONS_TAB)
    native.set_content_hidden(content, 0, 1)
    -- The escape menu's init only marks its layout dirty, and the first visual
    -- pass of an open places the category buttons visible then. A button MODS
    -- hides in that pass keeps (0, 0) until the menu opens again, so after
    -- GAME, straight to MODS, then OPTIONS, those buttons drew over GAMEPLAY
    -- (reported 2026-10-18). The native column is laid out first, all nine
    -- buttons visible; a button laid out once keeps its place while hidden.
    native.options_visual(content, 0)
    label_categories(view)
    if shown ~= 0 then select_category(content, shown, 0) end
    state.view = view
    clear_queued() -- the new page shows every value
    build_page(view, 0)
    note('Opened MODS tab: ' .. #view.mods .. ' mods.')
end

local function leave_view(view)
    local content = view.content
    local shown = view.page and view.page.index or get32(content + CURRENT_CATEGORY)
    view.page = nil
    -- The game lets the view go only once the edits are applied or discarded.
    drop_pending()
    put8(content + UNAPPLIED, 0)
    release_description(content)
    restore_categories(content)
    if shown >= MOD_BUTTONS then shown = CATEGORIES end -- no panel to deactivate
    select_category(content, shown, view.saved)
    state.view = nil
    if state.dirty then save_values() end
    note('Closed MODS tab.')
end

local function refresh_view(view)
    list_mods(view)
    view.revision = state.revision
    label_categories(view)
    local current = view.page and view.page.index or 0
    view.page = nil
    if not shows(view, current) then
        select_category(view.content, current, 0)
        current = 0
    end
    build_page(view, current)
end

local function maintain_view(view)
    local current = get32(view.content + CURRENT_CATEGORY)
    local page = view.page
    if view.revision ~= state.revision then
        refresh_view(view)
    elseif current ~= (page and page.index) then
        view.page = nil
        if shows(view, current) then
            -- The game already switched panels; replace its rows.
            build_page(view, current)
        else
            select_category(view.content, current, 0)
            build_page(view, 0)
        end
    elseif page and not page_intact(view) then
        build_page(view, current)
    end
    if view.page then
        if state.queued_any then apply_queued(view) end
        poll_page(view)
    end
end

-- For the other files and the update.
mom.escape_menu, mom.enter_view, mom.leave_view, mom.maintain_view = escape_menu, enter_view, leave_view, maintain_view
mom.update_apply, mom.update_visuals, mom.neutralize_dialog = update_apply, update_visuals, neutralize_dialog
mom.NO_ENTRIES, mom.MAX_MODS = NO_ENTRIES, MAX_MODS
end
mom_files.widgets = function(...)
-- The game's widgets MOM writes besides option rows (src/rows.lua): text
-- widgets, the MODS tab, the category buttons and the description box.
local mom = ...
local ffi = require('ffi')
local state, note = mom.state, mom.note
local get8, get32, getf, get64, put8, put32 = mom.get8, mom.get32, mom.getf, mom.get64, mom.put8, mom.put32
local vector, NATIVE_LABELS = mom.vector, mom.NATIVE_LABELS

-- Escape menu: one tab bar over the GAME, SOCIAL and OPTIONS contents. The
-- widget has eight tab buttons; the screen asks for three at initialisation.
local TAB_BAR, TAB_COUNT, TAB_CURRENT, TAB_LABELS = 1248, 57448, 57452, 57320
local TAB_BUTTON_STATE, TAB_BUTTON_ACTIVE, TAB_TEXT, TAB_STRIDE = 11004, 11021, 8296, 3400
local NATIVE_TABS, OPTIONS_TAB, MODS_TAB = 3, 2, 3
-- OPTIONS content: a column of nine category buttons and one panel per category.
local CATEGORY_BUTTON, CATEGORY_STRIDE, CATEGORY_TEXT = 816, 14920, 1928
local CATEGORIES, MOD_BUTTONS = 9, 8 -- the ninth (ACCOUNT) opens another screen
-- Description box beside the rows: a frame, a title and a body text. The game
-- fills it from the selected row's setting descriptor and caches that setting
-- (requested, shown); 156 means none. Heights are size.y x scale.y.
local DESCRIPTION_BOX, DESCRIPTION_FRAME, DESCRIPTION_TITLE, DESCRIPTION_BODY = 1315800, 272, 936, 1632
local DESCRIBED_SETTING, SHOWN_SETTING, NO_SETTING = 1318500, 1318476, 156
local WIDGET_HEIGHT, WIDGET_SCALE_Y = 16, 32
-- Text widgets hold a label ID at +272 and up to 14 format arguments
-- {key, type, value} of 24 bytes from +280, with their count at +616.
local LABEL, ARGUMENTS, ARGUMENT_COUNT = 272, 280, 616
-- '#COUNT' is a pure tag template, so a string COUNT argument shows any text
-- without borrowing a localization slot. The key is MurmurHash64A("COUNT") >> 32.
local TEXT_TEMPLATE, TEXT_KEY, STRING_ARGUMENT = 0xc67c7faf, 0xab2a7b35, 1

-- Text widgets ---------------------------------------------------------------

-- Text buffers live as long as the addon: a hidden widget may still point at
-- one after the MODS view closes, until the game re-initialises that widget.
-- Their addresses are kept as numbers, so a check compares without allocating.
local function text_buffer(text)
    local buffer = state.texts[text]
    if not buffer then
        buffer = ffi.new('char[?]', #text + 1, text)
        state.texts[text] = buffer
        state.text_addresses[text] = tonumber(ffi.cast('MOM_u64', buffer))
    end
    return buffer
end

local function text_argument(widget)
    for index = 0, math.min(get8(widget + ARGUMENT_COUNT), 14) - 1 do
        local record = widget + ARGUMENTS + 24 * index
        if get32(record) == TEXT_KEY then return record end
    end
    return nil
end

local function shows_text(widget, text)
    if get32(widget + LABEL) ~= TEXT_TEMPLATE then return false end
    local record = text_argument(widget)
    if not record or get32(record + 4) ~= STRING_ARGUMENT then return false end
    text_buffer(text)
    return get64(record + 8) == state.text_addresses[text]
end

local function show_text(widget, text)
    state.native.set_label(widget, TEXT_TEMPLATE)
    state.native.set_string_arg(widget, TEXT_KEY, text_buffer(text))
end

local function show_label(widget, label)
    state.native.clear_args(widget + LABEL)
    state.native.set_label(widget, label)
end

-- MODS tab and category buttons ----------------------------------------------

-- Adds MODS as the fourth native tab. The game draws it, its index and Q/E
-- (LB/RB) cycling; relabelling resets every button's state, so the current
-- tab's selected state is restored as the screen's opener does.
local tab_labels = ffi.new('MOM_u32[?]', NATIVE_TABS + 1)
local function ensure_mods_tab(screen)
    local bar = screen + TAB_BAR
    local count = get32(bar + TAB_COUNT)
    local title = bar + TAB_TEXT + TAB_STRIDE * MODS_TAB
    if count == NATIVE_TABS + 1 then
        if get32(bar + TAB_LABELS + 4 * MODS_TAB) ~= TEXT_TEMPLATE then return false end
        if not shows_text(title, state.mods_title) then show_text(title, state.mods_title) end
        return true
    end
    if count ~= NATIVE_TABS then return false end
    local current = get32(bar + TAB_CURRENT)
    if current >= NATIVE_TABS then return false end
    for index = 0, NATIVE_TABS - 1 do
        tab_labels[index] = get32(bar + TAB_LABELS + 4 * index)
        if tab_labels[index] ~= NATIVE_LABELS.tabs[index + 1] then return false end
    end
    tab_labels[MODS_TAB] = TEXT_TEMPLATE
    state.native.set_tab_labels(bar, tab_labels, NATIVE_TABS + 1)
    local button = bar + TAB_STRIDE * current
    put32(button + TAB_BUTTON_STATE, 3)
    put8(button + TAB_BUTTON_ACTIVE, 1)
    show_text(title, state.mods_title)
    if not state.mods_tab_logged then
        state.mods_tab_logged = true
        note('Added native MODS tab (current tab ' .. current .. ').')
    end
    return true
end

local function category_button(content, index)
    return content + CATEGORY_BUTTON + CATEGORY_STRIDE * index
end

-- view.buttons: the mod (or page control) on each button, false when none.
local function label_categories(view)
    local native = state.native
    for index = 0, CATEGORIES - 1 do
        local button = category_button(view.content, index)
        local mod = index < MOD_BUTTONS and view.buttons[index + 1]
        if mod or (index == 0 and #view.mods == 0) then
            show_text(button + CATEGORY_TEXT, mod and mod.title or state.empty_text)
            native.set_visible(button, 1)
        else
            native.set_visible(button, 0)
        end
    end
end

local function restore_categories(content)
    for index = 0, CATEGORIES - 1 do
        local button = category_button(content, index)
        show_label(button + CATEGORY_TEXT, NATIVE_LABELS.categories[index + 1])
        state.native.set_visible(button, 1)
    end
end

-- Description box ------------------------------------------------------------

local function text_height(widget)
    return getf(widget + WIDGET_HEIGHT) * getf(widget + WIDGET_SCALE_Y)
end

-- Shows the entry's description the way the game's set_description lays out a
-- setting's: title over body, the frame fitted to both. MOM rows share one
-- setting without a description, so the game itself only ever hides the box.
local function describe(view, entry)
    local native, box = state.native, view.content + DESCRIPTION_BOX
    view.described = entry
    local text = entry and entry.option.description
    if not text then native.hide_description(box, 1, 1); return end
    local title, body = box + DESCRIPTION_TITLE, box + DESCRIPTION_BODY
    show_text(title, entry.option.label)
    show_text(body, text)
    native.measure_text(body)
    native.measure_text(title)
    local title_height, body_height = text_height(title), text_height(body)
    native.set_position(body, vector(14, -title_height - 24))
    native.set_opacity(body, 1)
    native.set_size(box + DESCRIPTION_FRAME, vector(450, body_height + title_height + 7 + 72))
    native.hide_description(box, 0, 1)
end

-- Hands the box back to the game: hidden at once, MOM's text arguments gone,
-- and both setting caches cleared so OPTIONS fills it again.
local function release_description(content)
    local native, box = state.native, content + DESCRIPTION_BOX
    native.hide_description(box, 1, 0)
    native.clear_args(box + DESCRIPTION_TITLE + LABEL)
    native.clear_args(box + DESCRIPTION_BODY + LABEL)
    put32(content + DESCRIBED_SETTING, NO_SETTING)
    put32(content + SHOWN_SETTING, NO_SETTING)
end

-- For the other files and the update.
mom.show_text, mom.shows_text, mom.ensure_mods_tab = show_text, shows_text, ensure_mods_tab
mom.label_categories, mom.restore_categories = label_categories, restore_categories
mom.describe, mom.release_description = describe, release_description
mom.TAB_BAR, mom.TAB_CURRENT, mom.MODS_TAB, mom.OPTIONS_TAB = TAB_BAR, TAB_CURRENT, MODS_TAB, OPTIONS_TAB
mom.CATEGORIES, mom.MOD_BUTTONS, mom.TEXT_TEMPLATE = CATEGORIES, MOD_BUTTONS, TEXT_TEMPLATE
end
-- Native MODS tab on the Options screen for Steam build 26088801.
if rawget(_G, 'ModOptionsMenu') then return end
local ffi = require('ffi')
-- Texts and translations: mom_text = {module = src/bingus_text.lua, locales =
-- locales/}; the other source files: mom_files.<name> = src/<name>.lua as a
-- function, each run once below. The build places both ahead of this file as
-- locals (tests provide them as globals). translation: the text module, MOM's
-- own texts and every translation helper, in one table.
local translation = {T = mom_text.module}
-- Bingus Shared Runtime (src/bingus_runtime.lua and src/bingus_memory.lua,
-- vendored byte-identical; mom_files too, each returning its table): the
-- core's guard holds the update chain (below), and the read side hashes the
-- game's module files once per session for every mod (src/native.lua).
local runtime = mom_files.bingus_runtime()
local memory = mom_files.bingus_memory().new(runtime)

ffi.cdef [[
typedef unsigned char MOM_u8;
typedef unsigned int MOM_u32;
typedef unsigned long long MOM_u64;
]]
-- Widget positions and sizes: two floats passed by value in one register.
if not pcall(ffi.typeof, 'MOM_vec2') then ffi.cdef 'typedef struct { float x, y; } MOM_vec2;' end
-- MOM's guarded read under a private name. LuaJIT keeps the first prototype
-- declared for a name in the whole game, so the real name would get whatever
-- prototype another mod declared first; the __asm__ label names the export.
-- It takes its address as an integer, so a read allocates nothing (the
-- runtime's read takes a pointer, which interpreted code would box per read),
-- and reports the bytes read as two 32-bit halves.
ffi.cdef [[
int hd2mom_ReadProcessMemory(void *process, MOM_u64 address, void *buffer, size_t size,
                             MOM_u32 *received) __asm__("ReadProcessMemory");
]]
local process = memory.windows.kernel32.GetCurrentProcess()
local loader = rawget(_G, 'CowboyBingusModLoader')
local log_file
if loader and type(loader.open_log) == 'function' then
    pcall(function() log_file = loader.open_log('ModOptionsMenu.log') end)
end
local function note(message)
    if log_file then pcall(function() log_file:write(message .. '\n'); log_file:flush() end) end
end
-- MOM's own texts, in the game's language when a translation has them.
translation.tr = translation.T.new(mom_text.locales.en, mom_text.locales.bundled,
                                   function(message) note('Text: ' .. message) end)

-- mods: option categories in the order they were first registered (at most
-- 112); refused: the mods refused for want of a category, the first
-- refused_count of them. mods_page: the page of mods the category buttons
-- show when there are more than 8 (src/view.lua).
-- values: applied values; pending: the player's unapplied edits, by option id.
-- queued: options set from code whose rows the next checked step updates.
-- saved, written: the values file's entries (id -> text) and its text as last
-- read or written; dirty, save_timer: a save is due when the timer runs out;
-- save_failed: the last save failed (its failure is logged once).
-- mods_title, empty_text: MOM's own texts, resolved when the escape menu opens.
-- The update's error counts and status are the guard's (below):
-- BingusRuntime.statuses.ModOptionsMenu.
local state = {initialized = false, base = nil, native = nil, mods = {}, refused = {}, refused_count = 0,
               mods_page = 0, options = {}, option_count = 0, values = {}, pending = {}, pending_count = 0,
               queued = {}, queued_any = false, saved = nil, callbacks = {}, texts = {}, text_addresses = {},
               revision = 0, dirty = false, save_timer = 0, view = nil, mods_tab_logged = false, menu_seen = false,
               language = nil, mods_title = 'MODS', empty_text = 'NO MOD OPTIONS INSTALLED'}

-- Memory ---------------------------------------------------------------------

-- ReadProcessMemory guards the two reads that follow pointers not yet known
-- to be live, the UI stack and the escape menu screen, so a stale pointer
-- fails the read instead of the game. The address passes as an integer and
-- values land in reused buffers, so a read allocates nothing.
local read_memory = ffi.load('kernel32').hd2mom_ReadProcessMemory
local received, word = ffi.new('MOM_u32[2]'), ffi.new('MOM_u32[2]')
local function fill(target, address, size)
    return read_memory(process, address, target, size, received) ~= 0
        and received[0] == size and received[1] == 0
end
local function valid_pointer(value) return value >= 0x10000 and value < 0x800000000000 end
local function read_pointer(address)
    if not fill(word, address, 8) then return nil end
    local value = word[0] + word[1] * 4294967296
    return valid_pointer(value) and value or nil
end
-- translation.read: up to 16 bytes as a string, for the game's Text Language.
translation.bytes = ffi.new('MOM_u8[16]')
function translation.read(address, size)
    if size > 16 or not fill(translation.bytes, address, size) then return nil end
    return ffi.string(translation.bytes, size)
end
-- Everything else is loaded and stored directly: game.dll's image stays
-- mapped, and the escape menu screen is in use by the game while it is on top
-- of the UI stack, the same frames in which MOM writes to it and hands it to
-- native functions. Typed pointers based at address 0 turn an address into an
-- index, so a load returns a plain number: no system call, no allocation.
-- 32-bit and 64-bit fields are 4-byte aligned.
local BYTES, WORDS, FLOATS = ffi.cast('MOM_u8 *', 0), ffi.cast('MOM_u32 *', 0), ffi.cast('float *', 0)
local function get8(address) return BYTES[address] end
local function get32(address) return WORDS[address / 4] end
local function getf(address) return FLOATS[address / 4] end
local function get64(address) return WORDS[address / 4] + WORDS[address / 4 + 1] * 4294967296 end
-- Writes only touch the escape menu's heap objects, never game.dll sections.
local function put8(address, value) BYTES[address] = value end
local function put32(address, value) WORDS[address / 4] = value end
local function putf(address, value) FLOATS[address / 4] = value end
-- Reused position arguments; a call copies the value.
local PIVOT, position = ffi.new('MOM_vec2', 0.5, 1), ffi.new('MOM_vec2') -- row pivot and anchor
local function vector(x, y)
    position.x, position.y = x, y
    return position
end
-- Memory the game reads with 16-byte SSE loads (movaps faults on anything
-- less) must be 16-byte aligned, but ffi.new only guarantees 8. The aligned
-- part is carved from a larger zeroed block, which the caller keeps alive.
local function aligned(size)
    local block = ffi.new('MOM_u8[?]', size + 15)
    local offset = (16 - tonumber(ffi.cast('MOM_u64', block)) % 16) % 16
    return ffi.cast('MOM_u8 *', block) + offset, block
end

-- Source files ---------------------------------------------------------------

-- mom: what the source files share. Each file runs once, in this order, takes
-- what it uses as locals (so every call and constant costs what it did when
-- MOM was one file) and adds to mom what later files and the update use.
local mom = {memory = memory, loader = loader, note = note, translation = translation, state = state,
             fill = fill, valid_pointer = valid_pointer, read_pointer = read_pointer, get8 = get8, get32 = get32,
             getf = getf, get64 = get64, put8 = put8, put32 = put32, putf = putf, PIVOT = PIVOT, vector = vector,
             aligned = aligned}
mom_files.native(mom)  -- game.dll's functions and labels, verified once per session
mom_files.widgets(mom) -- text widgets, the MODS tab, category buttons, description box
mom_files.options(mom) -- registered texts, option values and the option model
mom_files.rows(mom)    -- option rows and category pages
mom_files.view(mom)    -- the MODS view: idle gate, entering and leaving, apply and dialog
mom_files.api(mom)     -- the API other mods use

-- Update ---------------------------------------------------------------------

local initialize, escape_menu, ensure_mods_tab = mom.initialize, mom.escape_menu, mom.ensure_mods_tab
local save_values, drop_pending = mom.save_values, mom.drop_pending
local enter_view, leave_view, maintain_view = mom.enter_view, mom.leave_view, mom.maintain_view
local update_apply, update_visuals, neutralize_dialog = mom.update_apply, mom.update_visuals, mom.neutralize_dialog
local TAB_BAR, TAB_CURRENT, MODS_TAB = mom.TAB_BAR, mom.TAB_CURRENT, mom.MODS_TAB

local function step(dt)
    if not state.initialized then initialize() end
    if not state.native then return end
    if state.dirty then
        state.save_timer = state.save_timer - (type(dt) == 'number' and dt or 0)
        if state.save_timer <= 0 then save_values() end
    end
    local screen, status = escape_menu()
    local view = state.view
    -- A view dropped with the menu (closed or rebuilt) never applies its edits;
    -- reopening the escape menu re-initialises every widget we touched.
    if status == 'closed' then
        state.menu_seen = false
        if view then state.view = nil; drop_pending(); note('Escape menu closed on the MODS tab.') end
        return
    end
    if status ~= 'open' then return end
    if not state.menu_seen then
        -- The menu just opened. Its OPTIONS tab is where the game's Text
        -- Language changes, so the language is read and the texts refreshed
        -- here, once per opening.
        state.menu_seen = true
        translation.observe()
        translation.tr:refresh()
        translation.refresh()
    end
    if view and view.screen ~= screen then state.view, view = nil, nil; drop_pending() end
    if not ensure_mods_tab(screen) then
        if view then state.view = nil; drop_pending() end
        return
    end
    local tab = get32(screen + TAB_BAR + TAB_CURRENT)
    if view then
        if tab ~= MODS_TAB then leave_view(view) else maintain_view(view) end
    elseif tab == MODS_TAB then
        enter_view(screen)
    end
    view = state.view
    if view then
        update_apply(view)
        update_visuals(view, type(dt) == 'number' and dt or 0)
        neutralize_dialog(view)
    end
end

_G.ModOptionsMenu = mom.api

-- Hands an open MODS view back to the game as on leaving the tab, but only
-- while its escape menu is still open on top: a covered or closed menu's view
-- is just dropped, as when the menu closes, and so is any view when the game
-- shuts down (touch_menu false), when MOM leaves the menu alone. The view is
-- dropped first, so nothing (the API included) touches the escape menu's rows
-- again. A value save still due is written.
local function reset_view(touch_menu)
    local view = state.view
    state.view = nil
    drop_pending()
    if view and touch_menu then
        local screen, status = escape_menu()
        if status == 'open' and screen == view.screen then leave_view(view) end
    end
    if state.dirty then save_values() end
end

-- The update guard (Bingus Shared Runtime) runs step before the previous
-- update every frame, and the previous update outside pcall, so an error below
-- reaches the game unchanged. Errors count in bursts that end after 3600
-- frames without one, MOM's own apart from those below: 8 in one burst stop
-- the step for the session (the API keeps working). Every argument and return
-- value pass through. stop: once, when the guard stops (the view goes back to
-- the game) or the game shuts down (a due save is written, the menu left
-- alone).
local function stop(reason)
    local done, why = pcall(reset_view, reason ~= 'shutdown')
    if not done then note('Options shutdown failed: ' .. tostring(why)) end
end
-- pause: an update below raised. The view goes back to the game the same way
-- and MOM starts afresh, as when the escape menu opens; the guard runs step
-- again once the updates below have returned on 60 frames in a row. A
-- hand-back that raises stops the guard instead.
local function pause()
    reset_view(true)
    state.menu_seen = false
end
-- The guard's lines (a burst's first error, a pause, a resume, the stop) go to
-- the log as the update's own lines did: 'Options update error: ...'.
local GUARD = 'ModOptionsMenu'
local function guard_line(line)
    if line:sub(1, #GUARD + 1) == GUARD .. ' ' then line = 'Options update ' .. line:sub(#GUARD + 2) end
    note(line)
end
local installed, failure = pcall(function()
    runtime.guard({name = GUARD, step = step, stop = stop, pause = pause, log = guard_line, env = _G}).install()
end)
note(installed and 'Mod Options Menu initialized.' or ('Mod Options Menu has no update: ' .. tostring(failure)))
